INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_14c386edc2c0f6', 'subj_phys', 'rotational-dynamics', 'Rotational motion', '\tau = rF\sin\theta, \quad \tau_{net} = I\alpha, \quad L = I\omega, \quad v = r\omega', 'Torque, Newton''s second law for rotation, angular momentum, and the link between linear and angular speed.', '[{"symbol":"\\tau","meaning":"torque","unit":"N·m"},{"symbol":"I","meaning":"rotational inertia","unit":"kg·m²"},{"symbol":"\\omega","meaning":"angular velocity","unit":"rad/s"},{"symbol":"\\alpha","meaning":"angular acceleration","unit":"rad/s²"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_2064840da8b635', 'subj_phys', 'fluids', 'Pressure, buoyancy and flow', 'P = P_0 + \rho g h, \quad F_b = \rho_f V g, \quad A_1 v_1 = A_2 v_2', 'Hydrostatic pressure, Archimedes'' principle and the continuity equation (Bernoulli''s equation is in the fluid-flow lesson).', '[{"symbol":"\\rho","meaning":"density","unit":"kg/m³"},{"symbol":"h","meaning":"depth","unit":"m"},{"symbol":"V","meaning":"displaced volume","unit":"m³"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_76364ba196605a', 'subj_phys', 'heat-thermodynamics', 'Heat and the first law', 'Q = mc\Delta T, \quad Q = mL, \quad \Delta U = Q - W', 'Heat for a temperature change, heat for a phase change, and the first law of thermodynamics (W is work done by the system).', '[{"symbol":"c","meaning":"specific heat","unit":"J/(kg·°C)"},{"symbol":"L","meaning":"latent heat","unit":"J/kg"},{"symbol":"U","meaning":"internal energy","unit":"J"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_773b99e1fcd847', 'subj_phys', 'photon-energy', 'Photon energy and the photoelectric effect', 'E = hf = \frac{hc}{\lambda}, \quad K_{max} = hf - \phi', 'Energy of a photon and the maximum kinetic energy of photoelectrons; h = 6.626 × 10⁻³⁴ J·s.', '[{"symbol":"h","meaning":"Planck''s constant","unit":"J·s"},{"symbol":"\\phi","meaning":"work function","unit":"eV"}]', 'published');

-- Lesson: angular-momentum-impulse
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_3ab470d2b794f7', 'angular-momentum-impulse', 'Angular momentum and angular impulse', 'Compute angular momentum for rigid bodies and point masses, and relate angular impulse to the change in angular momentum.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_99e256adfbe110', 'les_3ab470d2b794f7', 1, 'Compute L = Iω for a rigid body and L = mvr⊥ for a point mass.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_059333e3340184', 'les_3ab470d2b794f7', 2, 'Apply the angular impulse–momentum theorem, τΔt = ΔL.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6dfd0aefaef001', 'les_3ab470d2b794f7', 3, 'Read τ–t graphs: the area is the change in angular momentum.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_99e256adfbe110', 'les_3ab470d2b794f7', 'learn', 1, 'definition', '{"term":"Angular momentum","body":"A rigid body spinning about a fixed axis has $L = I\\omega$ (kg·m²/s). A point mass moving in a straight line also has angular momentum about any point not on its path: $L = mvr_\\perp$, where $r_\\perp$ is the perpendicular distance from the point to the line of motion."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_059333e3340184', 'les_3ab470d2b794f7', 'learn', 2, 'definition', '{"term":"Angular impulse","body":"$\\tau_{net}\\Delta t = \\Delta L$: a torque applied for a time changes angular momentum. On a graph of torque against time, the area under the curve is $\\Delta L$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6dfd0aefaef001', 'les_3ab470d2b794f7', 'learn', 3, 'worked_example', '{"title":"A 5 N·m torque acts for 2 s on a disk (I = 0.5 kg·m²) starting at rest","steps":[{"latex":"\\Delta L = 5(2) = 10\\ \\text{kg·m}^2/\\text{s}","explanation":""},{"latex":"\\omega = \\tfrac{10}{0.5} = 20\\ \\text{rad/s}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ffb2210e3cd90b', 'les_3ab470d2b794f7', 'learn', 4, 'worked_example', '{"title":"A 0.1 kg ball moves at 3 m/s along a line passing 0.5 m from a pivot","steps":[{"latex":"L = mvr_\\perp = 0.1(3)(0.5) = 0.15\\ \\text{kg·m}^2/\\text{s}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1152dd54cf2f3e', 'les_3ab470d2b794f7', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Spacecraft use small thrusters for a measured time to change their spin, and a figure skater''s push-off sets the angular momentum she keeps throughout a spin."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_99e256adfbe110', 'les_3ab470d2b794f7', 1, 'practice', 'numeric', 2, 'Find the angular momentum of a 2 kg solid disk (R = 0.3 m) spinning at 10 rad/s.', '{"answer":0.9,"tolerance":0.001,"unit":"kg·m²/s"}', '[]', '$\frac12(2)(0.09)(10)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_059333e3340184', 'les_3ab470d2b794f7', 2, 'practice', 'numeric', 2, 'A torque varies from 0 to 6 N·m linearly over 4 s. Find ΔL.', '{"answer":12,"unit":"kg·m²/s"}', '[]', 'Triangle area: $\frac12(4)(6)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6dfd0aefaef001', 'les_3ab470d2b794f7', 3, 'practice', 'multiple_choice', 2, 'A ball moves straight toward a pivot point. Its angular momentum about that point is…', '{"choices":["maximum","zero","negative","equal to mv"],"answer":1}', '[]', '$r_\perp = 0$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ffb2210e3cd90b', 'les_3ab470d2b794f7', 4, 'review', 'multiple_choice', 3, 'Two wheels get the same torque for the same time. The one with larger I ends with…', '{"choices":["more L","the same L but less ω","less L","the same ω"],"answer":1}', '[]', 'Same $\tau\Delta t$, same $\Delta L$; $\omega = \frac{L}{I}$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_acaf3225435500', 'subj_phys', 'rotation', 'Rotational motion', 'Angular kinematics, torque, rotational inertia and angular momentum.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_3ab470d2b794f7', (SELECT id FROM concepts WHERE slug = 'rotation'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_3ab470d2b794f7', (SELECT id FROM formulas WHERE slug = 'rotational-dynamics'), 1);

-- Lesson: buoyancy-archimedes
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_04da36649f8a07', 'buoyancy-archimedes', 'Buoyancy and Archimedes'' principle', 'Explain the buoyant force, use Archimedes'' principle to decide whether objects float or sink, and find the fraction submerged and apparent weight.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_678fe3f39e390a', 'les_04da36649f8a07', 1, 'State Archimedes'' principle: F_b equals the weight of the fluid displaced.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b49c875510b87a', 'les_04da36649f8a07', 2, 'Predict floating or sinking by comparing densities.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c67f11f244a182', 'les_04da36649f8a07', 3, 'Compute the fraction submerged and the apparent weight.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_678fe3f39e390a', 'les_04da36649f8a07', 'learn', 1, 'definition', '{"term":"Archimedes'' principle","body":"Pressure increases with depth, so a submerged object is pushed up harder on its bottom than down on its top. The net upward push, the buoyant force, equals the weight of the displaced fluid: $F_b = \\rho_f V_{sub}\\, g$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b49c875510b87a', 'les_04da36649f8a07', 'learn', 2, 'definition', '{"term":"Float or sink","body":"An object floats if it''s less dense than the fluid. Floating, it sinks until $F_b$ equals its weight, so the fraction submerged is $\\frac{\\rho_{obj}}{\\rho_f}$. A denser object sinks and has apparent weight $W - F_b$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c67f11f244a182', 'les_04da36649f8a07', 'learn', 3, 'worked_example', '{"title":"A 2 L block, fully submerged in water","steps":[{"latex":"F_b = 1000(0.002)(9.8) = 19.6\\ \\text{N}","explanation":"Whatever the block is made of."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ccbd118b8b0cc0', 'les_04da36649f8a07', 'learn', 4, 'worked_example', '{"title":"An iceberg (917 kg/m³) in seawater (1025 kg/m³)","steps":[{"latex":"\\tfrac{917}{1025} \\approx 0.895","explanation":"About 89% of the ice is below the surface."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a8f456a64f31b4', 'les_04da36649f8a07', 'experiment', 5, 'activity', '{"activity":"buoyancy","title":"Float or sink?","params":{"fluid":"water","density":600,"volume":2}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_27d468801db321', 'les_04da36649f8a07', 'experiment', 6, 'callout', '{"tone":"tip","title":"Try this","body":"With a 600 kg/m³ block, 60% sits underwater. Raise the density past 1000 and it sinks; then switch to glycerin and watch it float again."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f3afb128861260', 'les_04da36649f8a07', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Steel ships float because their hulls enclose air, making the average density low; submarines and fish adjust buoyancy by taking in or releasing water or gas."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_678fe3f39e390a', 'les_04da36649f8a07', 1, 'practice', 'numeric', 2, 'A 3 L rock of density 2500 kg/m³ lies underwater. Find its apparent weight.', '{"answer":44.1,"tolerance":0.1,"unit":"N"}', '[]', '$(2500 - 1000)(0.003)(9.8)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b49c875510b87a', 'les_04da36649f8a07', 2, 'practice', 'numeric', 1, 'Wood of density 800 kg/m³ floats in water. What percent is submerged?', '{"answer":80,"unit":"%"}', '[]', '$\frac{800}{1000}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c67f11f244a182', 'les_04da36649f8a07', 3, 'practice', 'multiple_choice', 2, 'A ship sails from a river (fresh water) into the sea. It…', '{"choices":["sinks lower","rises slightly","stays at the same level","sinks"],"answer":1}', '[]', 'Seawater is denser, so less volume is needed to displace the ship''s weight.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ccbd118b8b0cc0', 'les_04da36649f8a07', 4, 'review', 'multiple_choice', 3, 'Two blocks of equal volume, one aluminum and one lead, are fully submerged in water. The buoyant force is…', '{"choices":["larger on lead","larger on aluminum","the same on both","zero on lead"],"answer":2}', '[]', '$F_b$ depends only on the displaced volume.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_2064840da8b635', 'subj_phys', 'fluids', 'Fluids', 'Pressure, buoyancy and flow in liquids and gases.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_04da36649f8a07', (SELECT id FROM concepts WHERE slug = 'fluids'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_04da36649f8a07', (SELECT id FROM formulas WHERE slug = 'fluids'), 1);

-- Lesson: connected-objects-pulleys
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_77465ccdfdca90', 'connected-objects-pulleys', 'Connected objects and pulleys', 'Apply Newton''s second law to systems of objects joined by strings or contact, including blocks on tables and Atwood machines.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8c20886e066cbf', 'les_77465ccdfdca90', 1, 'Treat connected objects as a system to find a common acceleration.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b5cdae75aa2e6e', 'les_77465ccdfdca90', 2, 'Draw separate free-body diagrams to find tensions and contact forces.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d318ccfefa9092', 'les_77465ccdfdca90', 3, 'Analyze a table-and-hanging-mass system and an Atwood machine.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8c20886e066cbf', 'les_77465ccdfdca90', 'learn', 1, 'definition', '{"term":"Strategy","body":"Objects tied by an ideal (massless, unstretchable) string over a frictionless, massless pulley share the same acceleration magnitude, and the tension is the same all along the string. First treat the whole system as one object to find $a$; then use one object''s free-body diagram to find the tension."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b5cdae75aa2e6e', 'les_77465ccdfdca90', 'learn', 2, 'worked_example', '{"title":"A 2 kg cart on a frictionless table is tied over a pulley to a hanging 3 kg mass","steps":[{"latex":"a = \\tfrac{m_2 g}{m_1 + m_2} = \\tfrac{3(9.8)}{5} = 5.88\\ \\text{m/s}^2","explanation":"Only the hanging weight drives the system."},{"latex":"T = m_1 a = 2(5.88) \\approx 11.8\\ \\text{N}","explanation":"The string is the only horizontal force on the cart."}],"check":"Check: on the hanging mass, $m_2 g - T = 29.4 - 11.76 = 17.64 = m_2 a$. ✓"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d318ccfefa9092', 'les_77465ccdfdca90', 'learn', 3, 'worked_example', '{"title":"Atwood machine: 5 kg and 3 kg hang over a pulley","steps":[{"latex":"a = \\tfrac{(m_1 - m_2)g}{m_1 + m_2} = \\tfrac{2(9.8)}{8} = 2.45\\ \\text{m/s}^2","explanation":""},{"latex":"T = m_2(g + a) = 3(12.25) = 36.75\\ \\text{N}","explanation":"The lighter mass accelerates upward."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4c40a6831cc917', 'les_77465ccdfdca90', 'learn', 4, 'callout', '{"tone":"warning","title":"A common mistake","body":"The tension in the table example is not 29.4 N (the hanging weight). If it were, the hanging mass wouldn''t accelerate."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_50034d8e17415b', 'les_77465ccdfdca90', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Elevators use a counterweight like an Atwood machine, so the motor only supplies the difference in weights."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8c20886e066cbf', 'les_77465ccdfdca90', 1, 'practice', 'numeric', 2, 'A 10 N push acts on a 2 kg block that pushes a 3 kg block across a frictionless floor. Find the acceleration.', '{"answer":2,"unit":"m/s²"}', '[]', '$\frac{10}{5}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b5cdae75aa2e6e', 'les_77465ccdfdca90', 2, 'practice', 'numeric', 2, 'In that system, find the contact force on the 3 kg block.', '{"answer":6,"unit":"N"}', '[]', '$F = 3 \times 2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d318ccfefa9092', 'les_77465ccdfdca90', 3, 'practice', 'numeric', 3, 'An Atwood machine holds 4 kg and 6 kg. Find the acceleration.', '{"answer":1.96,"tolerance":0.01,"unit":"m/s²"}', '[]', '$\frac{2(9.8)}{10}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4c40a6831cc917', 'les_77465ccdfdca90', 4, 'review', 'multiple_choice', 3, 'If the two masses on an Atwood machine are equal, the system…', '{"choices":["accelerates at g","accelerates at g/2","stays at rest or keeps a constant velocity","can''t be analyzed"],"answer":2}', '[]', '$a = 0$ when $m_1 = m_2$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_77465ccdfdca90', (SELECT id FROM concepts WHERE slug = 'newtons-laws'));

-- Lesson: connecting-linear-rotational
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_10fa4bdb982f87', 'connecting-linear-rotational', 'Connecting linear and rotational motion', 'Relate a point''s linear motion to the rotation of the body it rides on, combine tangential and centripetal acceleration, and analyze belts, gears and unwinding strings.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_499aab5e992712', 'les_10fa4bdb982f87', 1, 'Use s = rθ, v = rω and a_t = rα for points on a rotating body.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_90aeb87be2f265', 'les_10fa4bdb982f87', 2, 'Combine tangential and centripetal acceleration into total acceleration.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d1b499df618b3f', 'les_10fa4bdb982f87', 3, 'Analyze belts, chains, gears and strings that don''t slip.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_499aab5e992712', 'les_10fa4bdb982f87', 'learn', 1, 'definition', '{"term":"Two kinds of acceleration","body":"A point at radius $r$ on a body with angular speed $\\omega$ and angular acceleration $\\alpha$ has a tangential acceleration $a_t = r\\alpha$ (changing its speed) and a centripetal acceleration $a_c = r\\omega^2$ (changing its direction). They are perpendicular: $a = \\sqrt{a_t^2 + a_c^2}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_90aeb87be2f265', 'les_10fa4bdb982f87', 'learn', 2, 'worked_example', '{"title":"A point 0.3 m from the axis when ω = 4 rad/s and α = 2 rad/s²","steps":[{"latex":"a_t = 0.3(2) = 0.6\\ \\text{m/s}^2","explanation":""},{"latex":"a_c = 0.3(4^2) = 4.8\\ \\text{m/s}^2","explanation":""},{"latex":"a = \\sqrt{0.6^2 + 4.8^2} \\approx 4.84\\ \\text{m/s}^2","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d1b499df618b3f', 'les_10fa4bdb982f87', 'learn', 3, 'definition', '{"term":"No-slip connections","body":"A belt, chain or rope that doesn''t slip moves at one linear speed everywhere along it. Where it meets two wheels, $r_1\\omega_1 = r_2\\omega_2$: the smaller wheel spins faster. A string unwinding from a spool has $v = R\\omega$ and $a = R\\alpha$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_eb1eee2e7a5abe', 'les_10fa4bdb982f87', 'learn', 4, 'worked_example', '{"title":"A bicycle: front sprocket 0.10 m turning at 6 rad/s; rear sprocket 0.04 m; wheel radius 0.35 m","steps":[{"latex":"v_{chain} = 0.10(6) = 0.6\\ \\text{m/s}","explanation":""},{"latex":"\\omega_{rear} = \\tfrac{0.6}{0.04} = 15\\ \\text{rad/s}","explanation":"The rear sprocket and wheel share this ω."},{"latex":"v_{bike} = 0.35(15) = 5.25\\ \\text{m/s}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_140a1b1c2834cd', 'les_10fa4bdb982f87', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Gear shifting trades pedaling speed for force, car transmissions do the same for engines, and hard drives and centrifuges are rated by the acceleration at their rim."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_499aab5e992712', 'les_10fa4bdb982f87', 1, 'practice', 'numeric', 2, 'Two gears mesh: a 0.05 m gear at 20 rad/s drives a 0.2 m gear. Find the large gear''s ω.', '{"answer":5,"unit":"rad/s"}', '[]', '$\frac{0.05(20)}{0.2}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_90aeb87be2f265', 'les_10fa4bdb982f87', 2, 'practice', 'numeric', 2, 'A bucket''s rope unwinds from a 0.1 m radius winch as the bucket falls with a = 2 m/s². Find the winch''s α.', '{"answer":20,"unit":"rad/s²"}', '[]', '$\frac{a}{R}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d1b499df618b3f', 'les_10fa4bdb982f87', 3, 'practice', 'multiple_choice', 2, 'A wheel spins at constant ω. A point on its rim has…', '{"choices":["no acceleration","only tangential acceleration","only centripetal acceleration","both"],"answer":2}', '[]', '$\alpha = 0$, so $a_t = 0$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_eb1eee2e7a5abe', 'les_10fa4bdb982f87', 4, 'review', 'multiple_choice', 3, 'Shifting a bike to a smaller rear sprocket (same pedaling) makes the bike…', '{"choices":["slower","faster but harder to pedal","easier to pedal","unchanged"],"answer":1}', '[]', 'Smaller $r_{rear}$, larger $\omega_{rear}$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_acaf3225435500', 'subj_phys', 'rotation', 'Rotational motion', 'Angular kinematics, torque, rotational inertia and angular momentum.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_10fa4bdb982f87', (SELECT id FROM concepts WHERE slug = 'rotation'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_10fa4bdb982f87', (SELECT id FROM formulas WHERE slug = 'rotational-dynamics'), 1);

-- Lesson: conservation-angular-momentum
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_35babba163838f', 'conservation-angular-momentum', 'Conservation of angular momentum', 'Apply conservation of angular momentum to changing shapes, rotational collisions and orbits, and track what happens to kinetic energy.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8ff77f60aa7290', 'les_35babba163838f', 1, 'Identify when angular momentum is conserved (no external torque).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_557d076c309fee', 'les_35babba163838f', 2, 'Solve problems where rotational inertia changes or objects join a rotating system.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_134d92ad4875f9', 'les_35babba163838f', 3, 'Compare kinetic energy before and after.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8ff77f60aa7290', 'les_35babba163838f', 'learn', 1, 'definition', '{"term":"Conservation","body":"If the net external torque on a system is zero, its total angular momentum is constant: $I_i\\omega_i = I_f\\omega_f$. Internal forces, like muscles pulling arms in, can change $I$ but not $L$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_557d076c309fee', 'les_35babba163838f', 'learn', 2, 'worked_example', '{"title":"A merry-go-round (I = 200 kg·m²) turns at 1 rad/s; a 40 kg child steps on at the rim, 2 m from the axis","steps":[{"latex":"I_f = 200 + 40(2^2) = 360\\ \\text{kg·m}^2","explanation":"The child joins as a point mass."},{"latex":"\\omega_f = \\tfrac{200(1)}{360} \\approx 0.56\\ \\text{rad/s}","explanation":""},{"latex":"K: 100\\ \\text{J} \\to \\tfrac12(360)(0.556^2) \\approx 56\\ \\text{J}","explanation":"Like a perfectly inelastic collision, kinetic energy is lost."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_134d92ad4875f9', 'les_35babba163838f', 'learn', 3, 'definition', '{"term":"Orbits","body":"Gravity points toward the Sun, so it exerts no torque about it, and a planet''s angular momentum is conserved. At closest approach (perihelion) the planet moves fastest: $r_p v_p = r_a v_a$. That''s Kepler''s second law."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e02bfd6d38b04c', 'les_35babba163838f', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Helicopters need a tail rotor to keep the body from spinning opposite the main rotor; neutron stars spin hundreds of times per second after collapsing."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8ff77f60aa7290', 'les_35babba163838f', 1, 'practice', 'numeric', 2, 'Earth''s distance from the Sun ranges from 1.47 to 1.52 × 10¹¹ m. Its speed at perihelion is 30.3 km/s. Find its speed at aphelion, in km/s.', '{"answer":29.3,"tolerance":0.05,"unit":"km/s"}', '[]', '$30.3 \cdot \frac{1.47}{1.52} \approx 29.3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_557d076c309fee', 'les_35babba163838f', 2, 'practice', 'numeric', 2, 'A 4 kg·m² turntable spins at 3 rad/s. A 1 kg·m² disk at rest drops onto it and sticks. Find the final ω.', '{"answer":2.4,"unit":"rad/s"}', '[]', '$\frac{12}{5}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_134d92ad4875f9', 'les_35babba163838f', 3, 'practice', 'multiple_choice', 2, 'A diver tucks in midair. Her angular momentum…', '{"choices":["increases","stays the same","decreases","becomes zero"],"answer":1}', '[]', 'No external torque about her center of mass (gravity acts there).');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e02bfd6d38b04c', 'les_35babba163838f', 4, 'review', 'multiple_choice', 3, 'If the Earth shrank to half its radius with the same mass, a day would be…', '{"choices":["twice as long","the same","one quarter as long","half as long"],"answer":2}', '[]', '$I \propto R^2$ drops to ¼, so ω is 4 times larger.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_acaf3225435500', 'subj_phys', 'rotation', 'Rotational motion', 'Angular kinematics, torque, rotational inertia and angular momentum.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_35babba163838f', (SELECT id FROM concepts WHERE slug = 'rotation'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_35babba163838f', (SELECT id FROM formulas WHERE slug = 'rotational-dynamics'), 1);

-- Lesson: density-pressure
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_f3fcfb2dc42b7a', 'density-pressure', 'Density and pressure', 'Use density and pressure, compute pressure at depth in a fluid, and explain hydraulic systems with Pascal''s principle.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_05e8a751f599ef', 'les_f3fcfb2dc42b7a', 1, 'Compute density ρ = m/V and pressure P = F/A.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_fbe7cf2992517e', 'les_f3fcfb2dc42b7a', 2, 'Find pressure at depth, P = P₀ + ρgh, and tell gauge pressure from absolute pressure.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_fb9d3c9d7ac643', 'les_f3fcfb2dc42b7a', 3, 'Apply Pascal''s principle to hydraulic lifts.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_05e8a751f599ef', 'les_f3fcfb2dc42b7a', 'learn', 1, 'definition', '{"term":"Density and pressure","body":"Density $\\rho = \\frac{m}{V}$ (water: 1000 kg/m³). Pressure is force per area: $P = \\frac{F}{A}$, in pascals (1 Pa = 1 N/m²). Atmospheric pressure at sea level is about 101,300 Pa."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fbe7cf2992517e', 'les_f3fcfb2dc42b7a', 'learn', 2, 'definition', '{"term":"Pressure at depth","body":"In a fluid at rest, $P = P_0 + \\rho g h$. The term $\\rho g h$ is the gauge pressure; $P$ is the absolute pressure. Pressure depends on depth only, not on the container''s shape."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fb9d3c9d7ac643', 'les_f3fcfb2dc42b7a', 'learn', 3, 'worked_example', '{"title":"A diver 10 m below the surface of fresh water","steps":[{"latex":"P_{gauge} = 1000(9.8)(10) = 98{,}000\\ \\text{Pa}","explanation":""},{"latex":"P = 101{,}300 + 98{,}000 = 199{,}300\\ \\text{Pa}","explanation":"About twice atmospheric pressure."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5450e6c39031f9', 'les_f3fcfb2dc42b7a', 'learn', 4, 'definition', '{"term":"Pascal''s principle","body":"Pressure applied to an enclosed fluid is transmitted undiminished everywhere in it. A hydraulic lift gives $\\frac{F_1}{A_1} = \\frac{F_2}{A_2}$: a small force on a small piston lifts a large load on a large piston, through a shorter distance."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_003ff7f380c25b', 'les_f3fcfb2dc42b7a', 'learn', 5, 'worked_example', '{"title":"A 100 N push on a piston; the output piston has 50 times the area","steps":[{"latex":"F_2 = 100 \\times 50 = 5000\\ \\text{N}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_26c8debc7ec6bf', 'les_f3fcfb2dc42b7a', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Car brakes and lifts are hydraulic; dams are thicker at the bottom where the pressure is highest; your ears pop as outside pressure changes."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_05e8a751f599ef', 'les_f3fcfb2dc42b7a', 1, 'practice', 'numeric', 1, 'A 2.7 kg block has a volume of 0.001 m³. Find its density.', '{"answer":2700,"unit":"kg/m³"}', '[]', '$\frac{2.7}{0.001}$ (aluminum).');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fbe7cf2992517e', 'les_f3fcfb2dc42b7a', 2, 'practice', 'numeric', 2, 'A 600 N person stands on 0.04 m² of shoe soles. Find the pressure.', '{"answer":15000,"unit":"Pa"}', '[]', '$\frac{600}{0.04}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fb9d3c9d7ac643', 'les_f3fcfb2dc42b7a', 3, 'practice', 'numeric', 2, 'Find the gauge pressure 3 m deep in a pool.', '{"answer":29400,"unit":"Pa"}', '[]', '$1000(9.8)(3)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5450e6c39031f9', 'les_f3fcfb2dc42b7a', 4, 'review', 'multiple_choice', 3, 'Three containers of different shapes are filled with water to the same depth. The pressure at the bottom is…', '{"choices":["greatest in the widest","greatest in the narrowest","the same in all three","greatest in the one with most water"],"answer":2}', '[]', 'Only depth matters.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_2064840da8b635', 'subj_phys', 'fluids', 'Fluids', 'Pressure, buoyancy and flow in liquids and gases.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_f3fcfb2dc42b7a', (SELECT id FROM concepts WHERE slug = 'fluids'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_f3fcfb2dc42b7a', (SELECT id FROM formulas WHERE slug = 'fluids'), 1);

-- Lesson: elastic-inelastic-collisions
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_69b21b91b21722', 'elastic-inelastic-collisions', 'Elastic and inelastic collisions', 'Classify collisions by what happens to kinetic energy, solve one-dimensional elastic collisions, and find the energy lost in inelastic ones.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_245cdce9ee5741', 'les_69b21b91b21722', 1, 'Distinguish elastic, inelastic and perfectly inelastic collisions.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d5de1086d11338', 'les_69b21b91b21722', 2, 'Solve 1D elastic collisions using momentum and kinetic energy conservation.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_70eaeb5604c6b9', 'les_69b21b91b21722', 3, 'Compute kinetic energy lost in inelastic collisions.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_245cdce9ee5741', 'les_69b21b91b21722', 'learn', 1, 'definition', '{"term":"Types of collision","body":"Momentum is conserved in every collision of an isolated system. Kinetic energy is conserved only in elastic collisions. In inelastic ones some KE becomes heat, sound and deformation; in perfectly inelastic ones the objects stick together and the most KE is lost."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d5de1086d11338', 'les_69b21b91b21722', 'learn', 2, 'definition', '{"term":"1D elastic collision, target at rest","body":"$v_1'' = \\frac{m_1 - m_2}{m_1 + m_2}v_1$ and $v_2'' = \\frac{2m_1}{m_1 + m_2}v_1$. Equal masses swap velocities, as in Newton''s cradle."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_70eaeb5604c6b9', 'les_69b21b91b21722', 'learn', 3, 'worked_example', '{"title":"A 2 kg cart at 3 m/s hits a 1 kg cart at rest, elastically","steps":[{"latex":"v_1'' = \\tfrac{1}{3}(3) = 1\\ \\text{m/s}","explanation":""},{"latex":"v_2'' = \\tfrac{4}{3}(3) = 4\\ \\text{m/s}","explanation":""},{"latex":"K_{before} = \\tfrac12(2)(9) = 9\\ \\text{J}","explanation":""},{"latex":"K_{after} = \\tfrac12(2)(1) + \\tfrac12(1)(16) = 9\\ \\text{J}","explanation":"Kinetic energy is conserved. ✓"}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3d57b80689123e', 'les_69b21b91b21722', 'learn', 4, 'worked_example', '{"title":"The same carts stick together instead","steps":[{"latex":"v'' = \\tfrac{2(3)}{3} = 2\\ \\text{m/s}","explanation":""},{"latex":"K'' = \\tfrac12(3)(4) = 6\\ \\text{J}","explanation":"3 J of kinetic energy is lost."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fb45b4ab9d177f', 'les_69b21b91b21722', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Crumple zones make car crashes very inelastic on purpose, so energy goes into deformation instead of passengers; billiard balls are nearly elastic."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_245cdce9ee5741', 'les_69b21b91b21722', 1, 'practice', 'numeric', 2, 'A 1000 kg car at 20 m/s hits a 1500 kg car at rest; they lock together. Find their speed.', '{"answer":8,"unit":"m/s"}', '[]', '$\frac{20{,}000}{2500}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d5de1086d11338', 'les_69b21b91b21722', 2, 'practice', 'numeric', 3, 'How much kinetic energy is lost in that crash?', '{"answer":120000,"unit":"J"}', '[]', '$200{,}000 - \frac12(2500)(64) = 120{,}000$ J.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_70eaeb5604c6b9', 'les_69b21b91b21722', 3, 'practice', 'multiple_choice', 2, 'A ball hits an identical ball at rest head-on, elastically. Afterward…', '{"choices":["both move at half speed","the first stops and the second moves at the original speed","both stop","the first bounces back"],"answer":1}', '[]', 'Equal masses swap velocities.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3d57b80689123e', 'les_69b21b91b21722', 4, 'review', 'multiple_choice', 3, 'In which collision is momentum NOT conserved (isolated system)?', '{"choices":["elastic","inelastic","perfectly inelastic","none of these"],"answer":3}', '[]', 'Momentum is conserved in all of them.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_69b21b91b21722', (SELECT id FROM concepts WHERE slug = 'momentum'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_69b21b91b21722', (SELECT id FROM formulas WHERE slug = 'momentum-impulse'), 1);

-- Lesson: fluid-flow-bernoulli
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_1ae3eb532798a7', 'fluid-flow-bernoulli', 'Fluid flow and Bernoulli''s equation', 'Use the continuity equation for flow through pipes of changing size, and apply Bernoulli''s equation to relate pressure, speed and height.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_30c3903557da8c', 'les_1ae3eb532798a7', 1, 'Apply the continuity equation A₁v₁ = A₂v₂.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_745d6f89173061', 'les_1ae3eb532798a7', 2, 'State and apply Bernoulli''s equation.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0a940f9c2b63f3', 'les_1ae3eb532798a7', 3, 'Find the speed of fluid draining from a tank (Torricelli''s result).');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_30c3903557da8c', 'les_1ae3eb532798a7', 'learn', 1, 'definition', '{"term":"Continuity","body":"For an incompressible fluid, the volume flow rate $Q = Av$ is the same everywhere along a pipe: $A_1 v_1 = A_2 v_2$. Where the pipe narrows, the fluid speeds up."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_745d6f89173061', 'les_1ae3eb532798a7', 'learn', 2, 'worked_example', '{"title":"Water leaves a 2 cm² hose at 1.5 m/s into a 0.5 cm² nozzle","steps":[{"latex":"v_2 = \\tfrac{A_1 v_1}{A_2} = \\tfrac{2(1.5)}{0.5} = 6\\ \\text{m/s}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0a940f9c2b63f3', 'les_1ae3eb532798a7', 'learn', 3, 'definition', '{"term":"Bernoulli''s equation","body":"Along a streamline of steady, non-viscous, incompressible flow: $P + \\frac12\\rho v^2 + \\rho g h = \\text{constant}$. It''s conservation of energy per unit volume, and where fluid moves faster its pressure is lower."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_597da3d75d7b77', 'les_1ae3eb532798a7', 'learn', 4, 'worked_example', '{"title":"Water speeds up from 2 m/s to 6 m/s in a horizontal pipe","steps":[{"latex":"P_1 - P_2 = \\tfrac12\\rho(v_2^2 - v_1^2)","explanation":""},{"latex":"P_1 - P_2 = \\tfrac12(1000)(36 - 4) = 16{,}000\\ \\text{Pa}","explanation":"The pressure is lower in the narrow, fast section."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5ded34b9a18490', 'les_1ae3eb532798a7', 'learn', 5, 'worked_example', '{"title":"Water drains from a hole 5 m below the surface of an open tank","steps":[{"latex":"v = \\sqrt{2gh} = \\sqrt{2(9.8)(5)} \\approx 9.9\\ \\text{m/s}","explanation":"The same speed as an object dropped 5 m."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6bdd9afb998178', 'les_1ae3eb532798a7', 'learn', 6, 'callout', '{"tone":"note","title":"Lift","body":"Bernoulli''s principle explains part of airplane lift (faster air over the wing, lower pressure), along with the wing deflecting air downward (Newton''s third law)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2f70d618845eab', 'les_1ae3eb532798a7', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Putting your thumb over a hose, perfume atomizers, carburetors and a shower curtain drawn inward by the moving spray."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_30c3903557da8c', 'les_1ae3eb532798a7', 1, 'practice', 'numeric', 2, 'A pipe''s radius halves. By what factor does the water speed change?', '{"answer":4}', '[]', 'Area scales as $r^2$, so the area is ¼ and the speed ×4.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_745d6f89173061', 'les_1ae3eb532798a7', 2, 'practice', 'numeric', 2, 'Find the drain speed from a hole 1.25 m below the water surface.', '{"answer":4.95,"tolerance":0.02,"unit":"m/s"}', '[]', '$\sqrt{2(9.8)(1.25)} \approx 4.95$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0a940f9c2b63f3', 'les_1ae3eb532798a7', 3, 'practice', 'numeric', 3, 'Air (ρ = 1.2 kg/m³) flows over a wing at 70 m/s and under it at 60 m/s. Find the pressure difference.', '{"answer":780,"tolerance":1,"unit":"Pa"}', '[]', '$\frac12(1.2)(4900 - 3600) = 780$ Pa.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_597da3d75d7b77', 'les_1ae3eb532798a7', 4, 'review', 'multiple_choice', 3, 'Two ships sailing close side by side tend to…', '{"choices":["drift apart","be pushed together","speed up","sink lower"],"answer":1}', '[]', 'Water between them moves faster, so its pressure is lower.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_2064840da8b635', 'subj_phys', 'fluids', 'Fluids', 'Pressure, buoyancy and flow in liquids and gases.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_1ae3eb532798a7', (SELECT id FROM concepts WHERE slug = 'fluids'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_1ae3eb532798a7', (SELECT id FROM formulas WHERE slug = 'fluids'), 1);

-- Lesson: internal-structure-density
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_6af57add17a9cb', 'internal-structure-density', 'Internal structure and density', 'Model fluids as collections of particles, use density to identify materials, compute average densities of mixtures, and test for purity with Archimedes'' method.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b1da5222fd9e08', 'les_6af57add17a9cb', 1, 'Describe what makes a substance a fluid, and the ideal-fluid model.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_52b8e398c263d3', 'les_6af57add17a9cb', 2, 'Use density ρ = m/V to identify materials and compute average densities.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6870703a990610', 'les_6af57add17a9cb', 3, 'Find an object''s density from its weight in air and in water.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b1da5222fd9e08', 'les_6af57add17a9cb', 'learn', 1, 'definition', '{"term":"Fluids","body":"Liquids and gases are fluids: their particles can slide past one another, so they flow and take the shape of their container. Liquids are nearly incompressible; gases compress easily. An ideal fluid is incompressible with no internal friction (viscosity), the model used in AP Physics."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_52b8e398c263d3', 'les_6af57add17a9cb', 'learn', 2, 'definition', '{"term":"Density","body":"$\\rho = \\frac{m}{V}$ is a property of the material, not the sample. Water is 1000 kg/m³ (1 g/cm³), aluminum 2700, iron 7870, gold 19,300 and air about 1.2. For a mixture, the average density is total mass divided by total volume."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6870703a990610', 'les_6af57add17a9cb', 'learn', 3, 'worked_example', '{"title":"A mix of 80% oil (920 kg/m³) and 20% water by volume","steps":[{"latex":"\\rho_{avg} = 0.8(920) + 0.2(1000) = 936\\ \\text{kg/m}^3","explanation":"By volume fractions."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_008eab389dae75', 'les_6af57add17a9cb', 'learn', 4, 'worked_example', '{"title":"Archimedes'' crown: 1.000 kg in air, apparent mass 0.940 kg in water","steps":[{"latex":"m_{water} = 1.000 - 0.940 = 0.060\\ \\text{kg}","explanation":"The mass of water the crown displaces."},{"latex":"V = \\tfrac{0.060}{1000} = 6.0\\times10^{-5}\\ \\text{m}^3","explanation":""},{"latex":"\\rho = \\tfrac{1.000}{6.0\\times10^{-5}} \\approx 16{,}700\\ \\text{kg/m}^3","explanation":"Less than gold''s 19,300, so the crown isn''t pure gold."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_aa128f1a06cc0f', 'les_6af57add17a9cb', 'experiment', 5, 'activity', '{"activity":"buoyancy","title":"Densities compared","params":{"fluid":"water","density":2700,"volume":1}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d746fea2ec7437', 'les_6af57add17a9cb', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Hydrometers measure battery acid and the sugar content of wine by how high they float; jewelers use the crown method to test precious metals."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b1da5222fd9e08', 'les_6af57add17a9cb', 1, 'practice', 'numeric', 1, 'A 500 cm³ block has a mass of 3.935 kg. Find its density in kg/m³.', '{"answer":7870,"unit":"kg/m³"}', '[]', '$\frac{3.935}{5\times10^{-4}}$ (iron).');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_52b8e398c263d3', 'les_6af57add17a9cb', 2, 'practice', 'numeric', 2, 'A metal object weighs 10.0 N in air and 8.0 N in water. Find its density.', '{"answer":5000,"unit":"kg/m³"}', '[]', '$F_b = 2$ N displaces $\frac{2}{9800}$ m³, so $\rho = 5 \times 1000$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6870703a990610', 'les_6af57add17a9cb', 3, 'practice', 'multiple_choice', 2, 'Cutting a block of wood in half changes its density by…', '{"choices":["halving it","doubling it","nothing","it depends"],"answer":2}', '[]', 'Density is a material property.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_008eab389dae75', 'les_6af57add17a9cb', 4, 'review', 'multiple_choice', 3, 'Which property separates liquids from gases in the ideal-fluid model?', '{"choices":["Viscosity","Compressibility","Color","Temperature"],"answer":1}', '[]', 'Liquids are nearly incompressible; gases are not.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_2064840da8b635', 'subj_phys', 'fluids', 'Fluids', 'Pressure, buoyancy and flow in liquids and gases.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_6af57add17a9cb', (SELECT id FROM concepts WHERE slug = 'fluids'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_6af57add17a9cb', (SELECT id FROM formulas WHERE slug = 'fluids'), 1);

-- Lesson: laws-of-thermodynamics
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_f483629af1a31a', 'laws-of-thermodynamics', 'Laws of thermodynamics', 'Apply the first law, ΔU = Q − W, understand entropy and the second law, and compute heat-engine and Carnot efficiencies.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8bac66dae5be33', 'les_f483629af1a31a', 1, 'State the zeroth, first and second laws of thermodynamics.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ec4324e044b69d', 'les_f483629af1a31a', 2, 'Apply ΔU = Q − W with correct signs.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e4fc6903355f54', 'les_f483629af1a31a', 3, 'Compute engine efficiency and the Carnot limit 1 − T_c/T_h.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8bac66dae5be33', 'les_f483629af1a31a', 'learn', 1, 'definition', '{"term":"Zeroth and first laws","body":"Zeroth: two systems each in equilibrium with a third are in equilibrium with each other, which is what makes thermometers work. First: energy is conserved, $\\Delta U = Q - W$, where $Q$ is heat added to the system and $W$ is work done by the system."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ec4324e044b69d', 'les_f483629af1a31a', 'learn', 2, 'worked_example', '{"title":"500 J of heat is added to a gas, which does 200 J of work pushing a piston","steps":[{"latex":"\\Delta U = 500 - 200 = 300\\ \\text{J}","explanation":"The gas''s internal energy, and so its temperature, rises."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e4fc6903355f54', 'les_f483629af1a31a', 'learn', 3, 'definition', '{"term":"Second law and entropy","body":"Heat flows spontaneously only from hot to cold, and the total entropy (disorder) of an isolated system never decreases. One consequence: no engine can turn heat entirely into work."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7ad62eed83eadd', 'les_f483629af1a31a', 'learn', 4, 'definition', '{"term":"Heat engines","body":"An engine takes heat $Q_h$ from a hot reservoir, does work $W$ and exhausts $Q_c$: $W = Q_h - Q_c$ and efficiency $e = \\frac{W}{Q_h}$. The best possible (Carnot) efficiency is $e = 1 - \\frac{T_c}{T_h}$, in kelvin."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_331526d0b0078f', 'les_f483629af1a31a', 'learn', 5, 'worked_example', '{"title":"An engine takes in 2000 J and exhausts 1400 J, running between 600 K and 300 K","steps":[{"latex":"W = 2000 - 1400 = 600\\ \\text{J}, \\ e = \\tfrac{600}{2000} = 30\\%","explanation":""},{"latex":"e_{Carnot} = 1 - \\tfrac{300}{600} = 50\\%","explanation":"The engine reaches 60% of the theoretical limit."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7da3c3cab93f88', 'les_f483629af1a31a', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Car engines reach about 25–30% efficiency and power plants 33–60%; refrigerators and heat pumps run the cycle backward, using work to move heat from cold to hot."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8bac66dae5be33', 'les_f483629af1a31a', 1, 'practice', 'numeric', 2, 'A gas loses 300 J of heat while 100 J of work is done on it (W = −100 J). Find ΔU.', '{"answer":-200,"unit":"J"}', '[]', '$-300 - (-100)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ec4324e044b69d', 'les_f483629af1a31a', 2, 'practice', 'numeric', 2, 'Find the Carnot efficiency, in percent, between 500 K and 350 K.', '{"answer":30,"unit":"%"}', '[]', '$1 - \frac{350}{500} = 0.30$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e4fc6903355f54', 'les_f483629af1a31a', 3, 'practice', 'multiple_choice', 2, 'For an ideal gas at constant temperature, ΔU = 0, so…', '{"choices":["Q = 0","W = 0","Q = W","Q = −W"],"answer":2}', '[]', '$0 = Q - W$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7ad62eed83eadd', 'les_f483629af1a31a', 4, 'review', 'multiple_choice', 3, 'An inventor claims an engine with 70% efficiency between 400 K and 300 K. This is…', '{"choices":["possible","impossible: the limit is 25%","possible if well insulated","impossible: the limit is 75%"],"answer":1}', '[]', '$1 - \frac{300}{400} = 25\%$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_6cf11d103edcfe', 'subj_phys', 'thermal-physics', 'Thermal physics', 'Temperature, heat, phase changes and the laws of thermodynamics.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_f483629af1a31a', (SELECT id FROM concepts WHERE slug = 'thermal-physics'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_f483629af1a31a', (SELECT id FROM formulas WHERE slug = 'heat-thermodynamics'), 1);

-- Lesson: momentum-vectors-systems
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_acb44a2a5925b8', 'momentum-vectors-systems', 'Linear momentum', 'Treat momentum as a vector, add the momenta of objects in a system, and connect total momentum to the velocity of the center of mass.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ccc5d32206a7ef', 'les_acb44a2a5925b8', 1, 'Compute momentum p = mv with direction, in one and two dimensions.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1a733b5d6220d3', 'les_acb44a2a5925b8', 2, 'Add momenta of objects as vectors to find the system''s total momentum.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_4e0a5244477235', 'les_acb44a2a5925b8', 3, 'Relate total momentum to the center of mass: p_total = M v_cm.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ccc5d32206a7ef', 'les_acb44a2a5925b8', 'learn', 1, 'definition', '{"term":"Momentum is a vector","body":"$\\vec p = m\\vec v$, in kg·m/s, pointing along the velocity. In one dimension, the sign gives the direction; in two dimensions, add components separately."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1a733b5d6220d3', 'les_acb44a2a5925b8', 'learn', 2, 'worked_example', '{"title":"A 2 kg puck moves east at 3 m/s; a 1 kg puck moves north at 4 m/s","steps":[{"latex":"\\vec p = (6,\\ 4)\\ \\text{kg·m/s}","explanation":""},{"latex":"|\\vec p| = \\sqrt{6^2 + 4^2} \\approx 7.21\\ \\text{kg·m/s}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4e0a5244477235', 'les_acb44a2a5925b8', 'learn', 3, 'definition', '{"term":"Systems","body":"A system''s total momentum is $\\vec p_{tot} = \\sum m_i\\vec v_i = M\\vec v_{cm}$. So the center of mass moves at $\\vec v_{cm} = \\frac{\\vec p_{tot}}{M}$, and Newton''s second law becomes $\\sum\\vec F_{ext} = \\frac{\\Delta\\vec p_{tot}}{\\Delta t}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_24591b89661cd6', 'les_acb44a2a5925b8', 'learn', 4, 'worked_example', '{"title":"A 3 kg cart at +2 m/s and a 1 kg cart at −4 m/s","steps":[{"latex":"p_{tot} = 3(2) + 1(-4) = 2\\ \\text{kg·m/s}","explanation":""},{"latex":"v_{cm} = \\tfrac{2}{4} = 0.5\\ \\text{m/s}","explanation":"This won''t change in any collision between them."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_538239b473326e', 'les_acb44a2a5925b8', 'learn', 5, 'callout', '{"tone":"warning","title":"A common mistake","body":"Two objects with equal and opposite momenta have zero total momentum, even though each is moving and the system has plenty of kinetic energy."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_24e068f2d2a8fd', 'les_acb44a2a5925b8', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Air-traffic and ship-collision models track momenta as vectors, and accident reconstruction adds the momenta of cars that skid off at angles."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ccc5d32206a7ef', 'les_acb44a2a5925b8', 1, 'practice', 'numeric', 1, 'Find the momentum of a 0.15 kg ball moving at 40 m/s.', '{"answer":6,"unit":"kg·m/s"}', '[]', '$0.15 \times 40$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1a733b5d6220d3', 'les_acb44a2a5925b8', 2, 'practice', 'numeric', 2, 'A 5 kg object moves at +2 m/s and a 2 kg object at −5 m/s. Find the total momentum.', '{"answer":0,"unit":"kg·m/s"}', '[]', '$10 - 10$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4e0a5244477235', 'les_acb44a2a5925b8', 3, 'practice', 'numeric', 2, 'Find the center-of-mass velocity of a 4 kg cart at 3 m/s and a 2 kg cart at rest.', '{"answer":2,"unit":"m/s"}', '[]', '$\frac{12}{6}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_24591b89661cd6', 'les_acb44a2a5925b8', 4, 'review', 'multiple_choice', 3, 'A ball bounces straight back off a wall with the same speed. Its momentum…', '{"choices":["is unchanged","changes by 2mv","changes by mv","becomes zero"],"answer":1}', '[]', '$\Delta p = mv - (-mv)$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_acb44a2a5925b8', (SELECT id FROM concepts WHERE slug = 'momentum'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_acb44a2a5925b8', (SELECT id FROM formulas WHERE slug = 'momentum-impulse'), 1);

-- Lesson: nuclear-decay-half-life
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_8b459e4b9f0bc2', 'nuclear-decay-half-life', 'Nuclear decay and half-life', 'Describe alpha, beta and gamma decay, balance nuclear equations, and use half-life to find remaining amounts and ages.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6e709169129141', 'les_8b459e4b9f0bc2', 1, 'Describe alpha, beta and gamma radiation and their penetrating power.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7f68ab316e292f', 'les_8b459e4b9f0bc2', 2, 'Balance nuclear equations by conserving mass number and charge.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7c5e28fc56adf5', 'les_8b459e4b9f0bc2', 3, 'Use N = N₀(½)^(t/T) to find remaining amounts and elapsed time.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6e709169129141', 'les_8b459e4b9f0bc2', 'learn', 1, 'definition', '{"term":"Types of decay","body":"Alpha ($^4_2\\text{He}$): mass number −4, atomic number −2; stopped by paper. Beta-minus ($^0_{-1}e$): a neutron becomes a proton, so atomic number +1; stopped by aluminum. Gamma: a high-energy photon; reduced by thick lead or concrete."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7f68ab316e292f', 'les_8b459e4b9f0bc2', 'learn', 2, 'worked_example', '{"title":"Balance the decays of uranium-238 (alpha) and carbon-14 (beta)","steps":[{"latex":"^{238}_{92}\\text{U} \\to\\, ^{234}_{90}\\text{Th} + ^4_2\\text{He}","explanation":"Top numbers and bottom numbers each balance."},{"latex":"^{14}_{6}\\text{C} \\to\\, ^{14}_{7}\\text{N} + ^0_{-1}e","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7c5e28fc56adf5', 'les_8b459e4b9f0bc2', 'learn', 3, 'definition', '{"term":"Half-life","body":"Each nucleus decays at random, but a large sample halves in a fixed time $T$, its half-life: $N = N_0\\left(\\frac12\\right)^{t/T}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a48b0c7e9ce29d', 'les_8b459e4b9f0bc2', 'learn', 4, 'worked_example', '{"title":"80 g of iodine-131 (half-life 8 days) after 24 days","steps":[{"latex":"\\tfrac{24}{8} = 3\\ \\text{half-lives}","explanation":""},{"latex":"80 \\to 40 \\to 20 \\to 10\\ \\text{g}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_58a0a539b8e5c2', 'les_8b459e4b9f0bc2', 'learn', 5, 'worked_example', '{"title":"A bone has 25% of its original carbon-14 (T = 5730 years)","steps":[{"latex":"\\tfrac14 = \\left(\\tfrac12\\right)^2 \\Rightarrow 2\\ \\text{half-lives}","explanation":""},{"latex":"t = 2(5730) = 11{,}460\\ \\text{years}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2696fb6a21bfbc', 'les_8b459e4b9f0bc2', 'experiment', 6, 'activity', '{"activity":"half-life","title":"Watch a sample decay","params":{"halfLife":5,"time":0}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_df39a3eb00a5ff', 'les_8b459e4b9f0bc2', 'experiment', 7, 'callout', '{"tone":"tip","title":"Try this","body":"Move time to 5, 10 and 15 years: about 200, 100 and 50 nuclei remain. Press \"New random sample\" a few times and notice that the count scatters around the curve, more noticeably when few nuclei are left."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_31ab9577b48e6f', 'les_8b459e4b9f0bc2', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"Carbon dating, smoke detectors (americium alpha source), medical tracers like technetium-99m (6-hour half-life) and cancer radiotherapy."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6e709169129141', 'les_8b459e4b9f0bc2', 1, 'practice', 'numeric', 2, 'What fraction of a sample remains after 4 half-lives? Give a decimal.', '{"answer":0.0625,"tolerance":0.0001}', '[]', '$\left(\frac12\right)^4 = \frac{1}{16}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7f68ab316e292f', 'les_8b459e4b9f0bc2', 2, 'practice', 'numeric', 2, 'A sample drops from 64 mg to 4 mg in 20 hours. Find the half-life.', '{"answer":5,"unit":"h"}', '[]', '$\frac{64}{4} = 16 = 2^4$: four half-lives in 20 h.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7c5e28fc56adf5', 'les_8b459e4b9f0bc2', 3, 'practice', 'multiple_choice', 2, 'Polonium-210 ($Z = 84$) undergoes alpha decay. The product is…', '{"choices":["Pb-206 (Z = 82)","Pb-210 (Z = 82)","Rn-214 (Z = 86)","Bi-210 (Z = 83)"],"answer":0}', '[]', 'Mass −4, atomic number −2.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a48b0c7e9ce29d', 'les_8b459e4b9f0bc2', 4, 'review', 'multiple_choice', 3, 'Which radiation needs the most shielding?', '{"choices":["alpha","beta","gamma","all equal"],"answer":2}', '[]', 'Gamma rays are uncharged, high-energy photons.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_0e1fb088df836c', 'subj_phys', 'modern-physics', 'Modern physics', 'Quantum and nuclear phenomena: photons, atoms and radioactivity.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_8b459e4b9f0bc2', (SELECT id FROM concepts WHERE slug = 'modern-physics'));

-- Lesson: orbiting-satellites
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_5927d85b372d3c', 'orbiting-satellites', 'Motion of orbiting satellites', 'Analyze circular and elliptical orbits with forces, energy and angular momentum; compute orbital speed, period, orbital energy and escape speed.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f519995412a941', 'les_5927d85b372d3c', 1, 'Derive v = √(GM/r) and T = 2πr/v for circular orbits.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3ab319e4c8d286', 'les_5927d85b372d3c', 2, 'Use total orbital energy E = −GMm/(2r).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_71d45f30216b2d', 'les_5927d85b372d3c', 3, 'Compute escape speed, and apply Kepler''s laws.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f519995412a941', 'les_5927d85b372d3c', 'learn', 1, 'definition', '{"term":"Circular orbits","body":"Gravity provides the centripetal force: $\\frac{GMm}{r^2} = \\frac{mv^2}{r}$, so $v = \\sqrt{\\frac{GM}{r}}$ and $T = \\frac{2\\pi r}{v}$. Squaring gives Kepler''s third law, $T^2 = \\frac{4\\pi^2}{GM}r^3$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3ab319e4c8d286', 'les_5927d85b372d3c', 'learn', 2, 'worked_example', '{"title":"The ISS at 400 km altitude (r = 6.77 × 10⁶ m)","steps":[{"latex":"v = \\sqrt{\\tfrac{(6.674\\times10^{-11})(5.97\\times10^{24})}{6.77\\times10^6}}","explanation":""},{"latex":"v \\approx 7670\\ \\text{m/s}","explanation":""},{"latex":"T = \\tfrac{2\\pi(6.77\\times10^6)}{7670}","explanation":""},{"latex":"T \\approx 5540\\ \\text{s} \\approx 92\\ \\text{min}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_71d45f30216b2d', 'les_5927d85b372d3c', 'learn', 3, 'definition', '{"term":"Orbital energy","body":"$K = \\frac{GMm}{2r}$ and $U = -\\frac{GMm}{r}$, so $E = -\\frac{GMm}{2r}$. A lower orbit has less total energy but more kinetic energy: drag makes a satellite spiral down and speed up. To escape completely, $E \\ge 0$: $v_{esc} = \\sqrt{\\frac{2GM}{R}} \\approx 11.2$ km/s from Earth''s surface."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_aa12b268dc430a', 'les_5927d85b372d3c', 'learn', 4, 'definition', '{"term":"Elliptical orbits","body":"In an ellipse, energy and angular momentum about the central body are both conserved. The satellite is fastest at closest approach, where $U$ is most negative."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_09402939665471', 'les_5927d85b372d3c', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"GPS satellites orbit at about 20,200 km with 12-hour periods; geostationary satellites at r ≈ 42,200 km take 24 hours and appear fixed in the sky."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f519995412a941', 'les_5927d85b372d3c', 1, 'practice', 'numeric', 2, 'A satellite''s orbital radius is multiplied by 4. By what factor does its period change?', '{"answer":8}', '[]', '$T \propto r^{3/2} = 4^{1.5}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3ab319e4c8d286', 'les_5927d85b372d3c', 2, 'practice', 'numeric', 2, 'By what factor does its orbital speed change?', '{"answer":0.5}', '[]', '$v \propto \frac{1}{\sqrt r}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_71d45f30216b2d', 'les_5927d85b372d3c', 3, 'practice', 'multiple_choice', 2, 'Astronauts on the ISS float because…', '{"choices":["there''s no gravity in orbit","they and the station are in free fall together","the station spins","air pressure holds them"],"answer":1}', '[]', 'Gravity there is still about 90% of surface gravity.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_aa12b268dc430a', 'les_5927d85b372d3c', 4, 'review', 'multiple_choice', 3, 'To move a satellite to a higher circular orbit, its total energy must…', '{"choices":["decrease","increase","stay the same","become zero"],"answer":1}', '[]', '$E = -\frac{GMm}{2r}$ rises toward zero as r grows, even though the final speed is lower.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_5927d85b372d3c', (SELECT id FROM concepts WHERE slug = 'circular-motion'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_5927d85b372d3c', (SELECT id FROM formulas WHERE slug = 'universal-gravitation'), 1);

-- Lesson: pendulum-period
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_d25eb7fd04a84c', 'pendulum-period', 'Frequency and period of SHM', 'Find the periods of mass–spring systems and pendulums, identify what they depend on (and don''t), and use measured periods to find g or k.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_de8c5dea69a907', 'les_d25eb7fd04a84c', 1, 'Use T = 2π√(m/k) for a mass on a spring and T = 2π√(L/g) for a simple pendulum.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_188711c9800ade', 'les_d25eb7fd04a84c', 2, 'Explain why period doesn''t depend on amplitude (for small oscillations).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b01dfb948e5e59', 'les_d25eb7fd04a84c', 3, 'Solve for k, g or L from a measured period.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_de8c5dea69a907', 'les_d25eb7fd04a84c', 'learn', 1, 'definition', '{"term":"Two oscillators","body":"Mass on a spring: $T = 2\\pi\\sqrt{\\frac{m}{k}}$, independent of gravity and amplitude. Simple pendulum (small angles): $T = 2\\pi\\sqrt{\\frac{L}{g}}$, independent of the bob''s mass and amplitude. Frequency is $f = \\frac1T$; angular frequency is $\\omega = 2\\pi f$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_188711c9800ade', 'les_d25eb7fd04a84c', 'learn', 2, 'worked_example', '{"title":"Periods of two oscillators","steps":[{"latex":"\\text{spring: } 2\\pi\\sqrt{\\tfrac{0.5}{200}} \\approx 0.314\\ \\text{s}","explanation":"A 0.5 kg mass on a 200 N/m spring."},{"latex":"\\text{pendulum: } 2\\pi\\sqrt{\\tfrac{1}{9.8}} \\approx 2.01\\ \\text{s}","explanation":"A 1 m pendulum on Earth."},{"latex":"\\text{on the Moon: } 2\\pi\\sqrt{\\tfrac{1}{1.62}} \\approx 4.94\\ \\text{s}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b01dfb948e5e59', 'les_d25eb7fd04a84c', 'learn', 3, 'worked_example', '{"title":"What length gives a 1 s period?","steps":[{"latex":"L = g\\left(\\tfrac{T}{2\\pi}\\right)^2 = \\tfrac{9.8}{4\\pi^2} \\approx 0.248\\ \\text{m}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c3515b0f4b2b79', 'les_d25eb7fd04a84c', 'experiment', 4, 'activity', '{"activity":"pendulum","title":"What changes the period?","params":{"planet":"earth","length":1,"amplitude":10}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0d6b5ebbb607a2', 'les_d25eb7fd04a84c', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"Quadruple the length from 0.5 m to 2 m: the period doubles. Raise the amplitude to 60°: the period grows by about 7%, so the small-angle rule is an approximation."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3384a87e301f36', 'les_d25eb7fd04a84c', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Pendulum clocks kept time for 300 years; geologists once measured local g with precise pendulums; tall buildings have tuned mass dampers that oscillate at the building''s own frequency."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_de8c5dea69a907', 'les_d25eb7fd04a84c', 1, 'practice', 'numeric', 2, 'Find the period of a 2 m pendulum on Earth.', '{"answer":2.84,"tolerance":0.01,"unit":"s"}', '[]', '$2\pi\sqrt{\frac{2}{9.8}}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_188711c9800ade', 'les_d25eb7fd04a84c', 2, 'practice', 'numeric', 2, 'A 0.4 kg mass on a spring has a period of 0.5 s. Find k, to the nearest N/m.', '{"answer":63,"tolerance":0.5,"unit":"N/m"}', '[]', '$k = \frac{4\pi^2 m}{T^2} \approx 63.2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b01dfb948e5e59', 'les_d25eb7fd04a84c', 3, 'practice', 'multiple_choice', 2, 'Doubling the mass on a spring multiplies the period by…', '{"choices":["2","√2","½","1"],"answer":1}', '[]', '$T \propto \sqrt m$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c3515b0f4b2b79', 'les_d25eb7fd04a84c', 4, 'review', 'multiple_choice', 3, 'A pendulum clock is taken from sea level to a high mountain, where g is slightly smaller. It runs…', '{"choices":["fast","slow","unchanged","backward"],"answer":1}', '[]', 'Smaller g gives a longer period, so fewer ticks per hour.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_d25eb7fd04a84c', (SELECT id FROM concepts WHERE slug = 'simple-harmonic-motion'));

-- Lesson: photoelectric-effect
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_6e92c9091ef1ad', 'photoelectric-effect', 'The photoelectric effect', 'Explain the photoelectric effect with photons, compute photon energies, and use K_max = hf − φ and the threshold frequency.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0d098520dfff94', 'les_6e92c9091ef1ad', 1, 'Describe the photoelectric experiment and why the wave model fails to explain it.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_168b64642b00c1', 'les_6e92c9091ef1ad', 2, 'Compute photon energy E = hf = hc/λ in joules and electron-volts.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_bad567eb9a9e44', 'les_6e92c9091ef1ad', 3, 'Use K_max = hf − φ and find the threshold frequency.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0d098520dfff94', 'les_6e92c9091ef1ad', 'learn', 1, 'definition', '{"term":"The puzzle","body":"Light shining on a metal can eject electrons. Experiments showed that below a threshold frequency no electrons come out, however bright the light; above it, electrons emerge instantly; and brighter light ejects more electrons, but not faster ones. Waves can''t explain this."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_168b64642b00c1', 'les_6e92c9091ef1ad', 'learn', 2, 'definition', '{"term":"Einstein''s photons","body":"Light comes in packets (photons) of energy $E = hf$, with $h = 6.626\\times10^{-34}$ J·s. One photon gives its energy to one electron, which needs at least the work function $\\phi$ to escape: $K_{max} = hf - \\phi$. 1 eV $= 1.602\\times10^{-19}$ J."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bad567eb9a9e44', 'les_6e92c9091ef1ad', 'learn', 3, 'worked_example', '{"title":"Energy of a 500 nm (green) photon","steps":[{"latex":"E = \\tfrac{hc}{\\lambda}","explanation":""},{"latex":"E = \\tfrac{(6.626\\times10^{-34})(3\\times10^8)}{5\\times10^{-7}}","explanation":""},{"latex":"E \\approx 3.98\\times10^{-19}\\ \\text{J} \\approx 2.48\\ \\text{eV}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a4931917271861', 'les_6e92c9091ef1ad', 'learn', 4, 'worked_example', '{"title":"250 nm UV light on sodium (φ = 2.28 eV)","steps":[{"latex":"E = \\tfrac{1240\\ \\text{eV·nm}}{250\\ \\text{nm}} \\approx 4.96\\ \\text{eV}","explanation":"The shortcut hc ≈ 1240 eV·nm."},{"latex":"K_{max} = 4.96 - 2.28 \\approx 2.68\\ \\text{eV}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_62ea2558166121', 'les_6e92c9091ef1ad', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Solar cells, camera sensors and the photomultipliers in medical scanners all rely on photons freeing electrons. Einstein''s 1921 Nobel Prize was for this explanation."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0d098520dfff94', 'les_6e92c9091ef1ad', 1, 'practice', 'numeric', 2, 'Find the threshold frequency for sodium (φ = 2.28 eV), in units of $10^{14}$ Hz.', '{"answer":5.51,"tolerance":0.02}', '[]', '$f_0 = \frac{\phi}{h} = \frac{2.28(1.602\times10^{-19})}{6.626\times10^{-34}}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_168b64642b00c1', 'les_6e92c9091ef1ad', 2, 'practice', 'numeric', 2, 'Find the energy of a 620 nm photon, in eV.', '{"answer":2,"tolerance":0.01,"unit":"eV"}', '[]', '$\frac{1240}{620}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bad567eb9a9e44', 'les_6e92c9091ef1ad', 3, 'practice', 'multiple_choice', 2, 'Red light (700 nm, 1.77 eV) shines on sodium. Electrons are…', '{"choices":["ejected slowly","not ejected, however bright the light","ejected only if the light is bright","ejected at 1.77 eV"],"answer":1}', '[]', '$1.77 < 2.28$ eV.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a4931917271861', 'les_6e92c9091ef1ad', 4, 'review', 'multiple_choice', 3, 'Doubling the intensity of light above the threshold frequency…', '{"choices":["doubles K_max","doubles the number of electrons ejected","halves the wavelength","has no effect"],"answer":1}', '[]', 'More photons, same energy each.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_0e1fb088df836c', 'subj_phys', 'modern-physics', 'Modern physics', 'Quantum and nuclear phenomena: photons, atoms and radioactivity.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_6e92c9091ef1ad', (SELECT id FROM concepts WHERE slug = 'modern-physics'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_6e92c9091ef1ad', (SELECT id FROM formulas WHERE slug = 'photon-energy'), 1);

-- Lesson: potential-energy-systems
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_ae478bf09c4897', 'potential-energy-systems', 'Potential energy of systems', 'Treat potential energy as belonging to a system, use gravitational (mgh and −GMm/r) and spring potential energy, and read energy graphs.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0889ccd7730bad', 'les_ae478bf09c4897', 1, 'Explain why potential energy belongs to a system of interacting objects.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_df8115803f5948', 'les_ae478bf09c4897', 2, 'Use ΔU = mgΔh near Earth and U = −GMm/r in general.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_660a12c41a06f9', 'les_ae478bf09c4897', 3, 'Use U = ½kx² for springs and read potential-energy graphs.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0889ccd7730bad', 'les_ae478bf09c4897', 'learn', 1, 'definition', '{"term":"Potential energy","body":"Potential energy is stored in the configuration of a system of objects that exert conservative forces on each other (gravity, springs, electric forces). A single isolated object has none; it''s the Earth–ball system that stores gravitational energy. For a conservative force, $\\Delta U = -W_{\\text{force}}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_df8115803f5948', 'les_ae478bf09c4897', 'learn', 2, 'definition', '{"term":"Gravitational","body":"Near Earth''s surface, $\\Delta U_g = mg\\Delta h$. In general, $U_g = -\\frac{GMm}{r}$, zero at infinite separation and negative for bound systems."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_660a12c41a06f9', 'les_ae478bf09c4897', 'learn', 3, 'worked_example', '{"title":"Lifting a 1000 kg satellite from the surface (r = 6.37 × 10⁶ m) to 400 km altitude","steps":[{"latex":"\\Delta U = GMm\\left(\\tfrac{1}{R} - \\tfrac{1}{R + h}\\right) \\approx 3.70\\times10^9\\ \\text{J}","explanation":""},{"latex":"mgh = 1000(9.8)(4\\times10^5) = 3.92\\times10^9\\ \\text{J}","explanation":"mgh overestimates by about 6% because g weakens with altitude."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_26447f3d0d1681', 'les_ae478bf09c4897', 'learn', 4, 'definition', '{"term":"Spring","body":"$U_s = \\frac12 kx^2$, zero at the natural length and always positive. A potential-energy graph $U(x)$ shows the force as minus its slope; minima are stable equilibria where the object oscillates."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0faf97a31172eb', 'les_ae478bf09c4897', 'learn', 5, 'worked_example', '{"title":"A 200 N/m spring compressed 0.1 m","steps":[{"latex":"U = \\tfrac12(200)(0.1)^2 = 1\\ \\text{J}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b6817d4d4327d1', 'les_ae478bf09c4897', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Pumped-storage hydroelectric plants store energy as water''s gravitational potential energy, and bows store it as elastic potential energy."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0889ccd7730bad', 'les_ae478bf09c4897', 1, 'practice', 'numeric', 1, 'Find the change in gravitational potential energy when a 2 kg book is lifted 3 m.', '{"answer":58.8,"tolerance":0.01,"unit":"J"}', '[]', '$2(9.8)(3)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_df8115803f5948', 'les_ae478bf09c4897', 2, 'practice', 'numeric', 2, 'A spring launcher (k = 400 N/m) is compressed 0.05 m and launches a 0.02 kg ball horizontally. Find the launch speed.', '{"answer":7.07,"tolerance":0.02,"unit":"m/s"}', '[]', '$\frac12kx^2 = \frac12mv^2$, so $v = x\sqrt{k/m}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_660a12c41a06f9', 'les_ae478bf09c4897', 3, 'practice', 'multiple_choice', 2, 'The gravitational potential energy of a satellite–Earth system is negative because…', '{"choices":["the satellite moves","zero is chosen at infinite separation, and the system is bound","gravity is repulsive","of an error in sign"],"answer":1}', '[]', 'You must add energy to separate them to infinity.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_26447f3d0d1681', 'les_ae478bf09c4897', 4, 'review', 'multiple_choice', 3, 'On a U(x) graph, an object is at a point where the slope is positive. The force on it points…', '{"choices":["toward +x","toward −x","nowhere","up"],"answer":1}', '[]', '$F = -\frac{dU}{dx}$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_ae478bf09c4897', (SELECT id FROM concepts WHERE slug = 'energy'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_ae478bf09c4897', (SELECT id FROM formulas WHERE slug = 'work-energy'), 1);

-- Lesson: relative-velocity
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_b048f6d5e5058d', 'relative-velocity', 'Relative velocity', 'Describe motion from different reference frames, add velocities as vectors, and solve river-crossing and crosswind problems.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_65dee9d7d3e49e', 'les_b048f6d5e5058d', 1, 'Explain that velocity depends on the reference frame.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_82871a6a8e920c', 'les_b048f6d5e5058d', 2, 'Add relative velocities: v(A rel C) = v(A rel B) + v(B rel C).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3aa44e5ec11ad5', 'les_b048f6d5e5058d', 3, 'Solve boat-in-a-current and plane-in-a-wind problems with vector components.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_65dee9d7d3e49e', 'les_b048f6d5e5058d', 'learn', 1, 'definition', '{"term":"Reference frames","body":"A velocity is always measured relative to something. Velocities chain like subscripts cancelling: $\\vec v_{AC} = \\vec v_{AB} + \\vec v_{BC}$. A passenger walking forward at 1.5 m/s on a train moving at 20 m/s moves at 21.5 m/s relative to the ground."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_82871a6a8e920c', 'les_b048f6d5e5058d', 'learn', 2, 'worked_example', '{"title":"A boat heads straight across an 80 m river at 4 m/s; the current is 3 m/s downstream","steps":[{"latex":"v = \\sqrt{4^2 + 3^2} = 5\\ \\text{m/s}","explanation":"Speed relative to the shore."},{"latex":"\\theta = \\tan^{-1}\\tfrac{3}{4} \\approx 36.9°","explanation":"Angle downstream from straight across."},{"latex":"t = \\tfrac{80}{4} = 20\\ \\text{s}","explanation":"Only the cross-river component moves the boat across."},{"latex":"\\text{drift} = 3 \\times 20 = 60\\ \\text{m}","explanation":"Distance carried downstream."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3aa44e5ec11ad5', 'les_b048f6d5e5058d', 'learn', 3, 'worked_example', '{"title":"To land directly across, a 5 m/s boat must aim upstream against the 3 m/s current","steps":[{"latex":"\\sin\\theta = \\tfrac{3}{5} \\Rightarrow \\theta \\approx 36.9°","explanation":"Upstream from straight across, so the upstream component cancels the current."},{"latex":"v_{\\text{across}} = \\sqrt{5^2 - 3^2} = 4\\ \\text{m/s}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_672a7b9bebcd1f', 'les_b048f6d5e5058d', 'experiment', 4, 'activity', '{"activity":"vectors","title":"Add the boat and current vectors"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4ff87f8eaa8b03', 'les_b048f6d5e5058d', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Pilots compute a heading that corrects for wind (the \"wind triangle\"), and ships and swimmers in rip currents use the same reasoning."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_65dee9d7d3e49e', 'les_b048f6d5e5058d', 1, 'practice', 'numeric', 2, 'A plane flies north at 200 km/h relative to the air, with a 50 km/h wind blowing east. Find its ground speed, to the nearest km/h.', '{"answer":206,"tolerance":1,"unit":"km/h"}', '[]', '$\sqrt{200^2 + 50^2} \approx 206$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_82871a6a8e920c', 'les_b048f6d5e5058d', 2, 'practice', 'numeric', 1, 'You walk toward the back of a train at 2 m/s; the train moves forward at 25 m/s. Find your speed relative to the ground.', '{"answer":23,"unit":"m/s"}', '[]', '$25 - 2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3aa44e5ec11ad5', 'les_b048f6d5e5058d', 3, 'practice', 'numeric', 2, 'In the river example, how long does the boat aiming upstream (5 m/s) take to cross 80 m?', '{"answer":20,"unit":"s"}', '[]', 'Cross component 4 m/s: $\frac{80}{4}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_672a7b9bebcd1f', 'les_b048f6d5e5058d', 4, 'review', 'multiple_choice', 3, 'Increasing the current speed changes the straight-across crossing time (boat aimed straight across) by…', '{"choices":["making it longer","making it shorter","not at all","doubling it"],"answer":2}', '[]', 'The current is perpendicular to the crossing direction; only the drift changes.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_b048f6d5e5058d', (SELECT id FROM concepts WHERE slug = 'kinematics'));

-- Lesson: rolling-motion
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_65c3e1bb21482c', 'rolling-motion', 'Rolling', 'Describe rolling without slipping, split kinetic energy into translational and rotational parts, and predict which shape wins a race down a ramp.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_96d1e1f9f336f7', 'les_65c3e1bb21482c', 1, 'Use the rolling condition v = Rω.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_61a20a0c06b098', 'les_65c3e1bb21482c', 2, 'Compute total kinetic energy K = ½mv²(1 + β), with β = I/(mR²).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7c0f634e901c84', 'les_65c3e1bb21482c', 3, 'Find speeds and accelerations of rolling objects on inclines.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_96d1e1f9f336f7', 'les_65c3e1bb21482c', 'learn', 1, 'definition', '{"term":"Rolling without slipping","body":"The contact point is momentarily at rest, so $v_{cm} = R\\omega$ and $a_{cm} = R\\alpha$. Static friction provides the torque that makes the object spin, but it does no work, because the contact point doesn''t slide."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_61a20a0c06b098', 'les_65c3e1bb21482c', 'learn', 2, 'definition', '{"term":"Energy","body":"$K = \\frac12mv^2 + \\frac12I\\omega^2 = \\frac12mv^2(1 + \\beta)$ with $\\beta = \\frac{I}{mR^2}$ (sphere $\\frac25$, disk $\\frac12$, hoop 1). Rolling from rest down a height $h$: $v = \\sqrt{\\frac{2gh}{1 + \\beta}}$, the same for any mass or radius."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7c0f634e901c84', 'les_65c3e1bb21482c', 'learn', 3, 'worked_example', '{"title":"Speeds at the bottom of a 1 m drop","steps":[{"latex":"\\text{sphere: } \\sqrt{\\tfrac{2(9.8)}{1.4}} \\approx 3.74\\ \\text{m/s}","explanation":""},{"latex":"\\text{disk: } \\sqrt{\\tfrac{19.6}{1.5}} \\approx 3.61\\ \\text{m/s}","explanation":""},{"latex":"\\text{hoop: } \\sqrt{\\tfrac{19.6}{2}} \\approx 3.13\\ \\text{m/s}","explanation":""},{"latex":"\\text{frictionless block: } \\sqrt{19.6} \\approx 4.43\\ \\text{m/s}","explanation":"No energy goes into spinning."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a52495114f85e5', 'les_65c3e1bb21482c', 'experiment', 4, 'activity', '{"activity":"rolling-race","title":"Race the shapes","params":{"height":1,"angle":20}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0b6441f4eb7b11', 'les_65c3e1bb21482c', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"Change the height and angle: the finishing order never changes, and the speeds at the bottom depend only on the height."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7e271d503c05fc', 'les_65c3e1bb21482c', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Bowling balls, wheels and tires. Racers lighten wheel rims specifically, because rim mass counts double: it adds both weight and rotational inertia."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_96d1e1f9f336f7', 'les_65c3e1bb21482c', 1, 'practice', 'numeric', 2, 'What fraction of a rolling solid disk''s kinetic energy is rotational? Give a decimal to two places.', '{"answer":0.33,"tolerance":0.01}', '[]', '$\frac{\beta}{1 + \beta} = \frac{0.5}{1.5}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_61a20a0c06b098', 'les_65c3e1bb21482c', 2, 'practice', 'numeric', 2, 'A bowling ball (solid sphere) rolls at 5 m/s. What is ω if R = 0.11 m? Round to one decimal place.', '{"answer":45.5,"tolerance":0.1,"unit":"rad/s"}', '[]', '$\frac{5}{0.11}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7c0f634e901c84', 'les_65c3e1bb21482c', 3, 'practice', 'numeric', 3, 'Find the acceleration of a solid sphere rolling down a 30° incline.', '{"answer":3.5,"tolerance":0.01,"unit":"m/s²"}', '[]', '$\frac{g\sin 30°}{1.4} = \frac{4.9}{1.4}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a52495114f85e5', 'les_65c3e1bb21482c', 4, 'review', 'multiple_choice', 3, 'A heavy and a light solid cylinder of different radii roll down the same ramp. Which reaches the bottom first?', '{"choices":["the heavy one","the light one","they tie","the larger one"],"answer":2}', '[]', 'The speed depends only on h and β.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_acaf3225435500', 'subj_phys', 'rotation', 'Rotational motion', 'Angular kinematics, torque, rotational inertia and angular momentum.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_65c3e1bb21482c', (SELECT id FROM concepts WHERE slug = 'rotation'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_65c3e1bb21482c', (SELECT id FROM formulas WHERE slug = 'rotational-dynamics'), 1);

-- Lesson: rotational-equilibrium
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_1c9f25a420af74', 'rotational-equilibrium', 'Rotational equilibrium', 'Apply Newton''s first law in rotational form to extended objects, choose pivots wisely, and solve beam and ladder problems.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_84a3509a10d2c3', 'les_1c9f25a420af74', 1, 'State Newton''s first law in rotational form: zero net torque means constant angular velocity.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ac29e6008690e1', 'les_1c9f25a420af74', 2, 'Treat an extended object''s weight as acting at its center of mass.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1b6c6655b439bf', 'les_1c9f25a420af74', 3, 'Solve beam and ladder equilibrium problems with ΣF = 0 and Στ = 0.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_84a3509a10d2c3', 'les_1c9f25a420af74', 'learn', 1, 'definition', '{"term":"Rotational first law","body":"If the net torque on a rigid object is zero, its angular velocity stays constant, possibly zero. Static equilibrium requires both $\\sum\\vec F = 0$ and $\\sum\\tau = 0$ about every point, so you may choose the pivot. Pick the point where an unknown force acts: that force then drops out of the torque equation."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ac29e6008690e1', 'les_1c9f25a420af74', 'learn', 2, 'definition', '{"term":"Extended objects","body":"Gravity on an extended object acts as if at its center of mass: the middle, for a uniform beam. Torques that would turn the object counterclockwise are positive; clockwise ones are negative."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1b6c6655b439bf', 'les_1c9f25a420af74', 'learn', 3, 'worked_example', '{"title":"A uniform 5 m, 20 kg ladder leans at 60° to the floor against a frictionless wall","steps":[{"latex":"\\tau_{base}: N_w L\\sin 60° = mg\\tfrac{L}{2}\\cos 60°","explanation":"Taking torques about the base removes both floor forces."},{"latex":"N_w = \\tfrac{196(0.5)}{2(0.866)} \\approx 56.6\\ \\text{N}","explanation":""},{"latex":"f_{floor} = 56.6\\ \\text{N},\\ N_{floor} = 196\\ \\text{N}","explanation":"From ΣF = 0, horizontal and vertical."},{"latex":"\\mu_s \\ge \\tfrac{56.6}{196} \\approx 0.29","explanation":"The minimum friction coefficient to keep it from slipping."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ed33391461382f', 'les_1c9f25a420af74', 'experiment', 4, 'activity', '{"activity":"torque-balance","title":"Find the balance point","params":{"m1":5,"d1":2,"m2":8,"d2":1}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9074729f7e5bf4', 'les_1c9f25a420af74', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Ladder safety rules (the 4-to-1 rule, about 75°), cantilevered balconies and the forces in your forearm when holding a weight."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_84a3509a10d2c3', 'les_1c9f25a420af74', 1, 'practice', 'numeric', 2, 'A uniform 6 m, 30 kg beam is supported at its left end and 4 m from the left. Find the force from the support at 4 m.', '{"answer":220.5,"tolerance":0.1,"unit":"N"}', '[]', 'About the left end: $F(4) = 294(3)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ac29e6008690e1', 'les_1c9f25a420af74', 2, 'practice', 'numeric', 3, 'For the same beam, find the force at the left end.', '{"answer":73.5,"tolerance":0.1,"unit":"N"}', '[]', '$294 - 220.5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1b6c6655b439bf', 'les_1c9f25a420af74', 3, 'practice', 'multiple_choice', 2, 'A ladder is more likely to slip when…', '{"choices":["it''s nearly vertical","its angle with the floor is small","the wall is frictionless and the ladder is short","a person stands at the bottom"],"answer":1}', '[]', 'A shallow angle needs a larger wall force and so more friction.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ed33391461382f', 'les_1c9f25a420af74', 4, 'review', 'multiple_choice', 3, 'An object has zero net force but a nonzero net torque. It…', '{"choices":["is in equilibrium","starts to rotate","accelerates linearly","doesn''t move"],"answer":1}', '[]', 'Both conditions are needed for equilibrium.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_acaf3225435500', 'subj_phys', 'rotation', 'Rotational motion', 'Angular kinematics, torque, rotational inertia and angular momentum.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_1c9f25a420af74', (SELECT id FROM concepts WHERE slug = 'rotation'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_1c9f25a420af74', (SELECT id FROM formulas WHERE slug = 'rotational-dynamics'), 1);

-- Lesson: rotational-inertia-angular-momentum
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_0625c4e2137a40', 'rotational-inertia-angular-momentum', 'Rotational inertia and angular momentum', 'Understand rotational inertia, apply τ = Iα, compute rotational kinetic energy, and use conservation of angular momentum.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e3d40f8c27d737', 'les_0625c4e2137a40', 1, 'Explain how rotational inertia depends on mass and its distance from the axis.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_cd4c49722cb435', 'les_0625c4e2137a40', 2, 'Apply Newton''s second law for rotation, τ = Iα.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1516252e6a1d34', 'les_0625c4e2137a40', 3, 'Use K = ½Iω² and conservation of angular momentum, L = Iω.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e3d40f8c27d737', 'les_0625c4e2137a40', 'learn', 1, 'definition', '{"term":"Rotational inertia","body":"$I = \\sum m r^2$: mass far from the axis counts more. Common shapes of mass $M$ and radius $R$: hoop $MR^2$; solid disk $\\frac12 MR^2$; solid sphere $\\frac25 MR^2$. Newton''s second law for rotation: $\\tau_{net} = I\\alpha$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cd4c49722cb435', 'les_0625c4e2137a40', 'learn', 2, 'worked_example', '{"title":"A 2 kg solid disk of radius 0.5 m with a 1 N·m net torque","steps":[{"latex":"I = \\tfrac12(2)(0.5)^2 = 0.25\\ \\text{kg·m}^2","explanation":""},{"latex":"\\alpha = \\tfrac{\\tau}{I} = \\tfrac{1}{0.25} = 4\\ \\text{rad/s}^2","explanation":""},{"latex":"\\text{at}\\ \\omega = 4\\ \\text{rad/s: } K = \\tfrac12(0.25)(4^2) = 2\\ \\text{J}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1516252e6a1d34', 'les_0625c4e2137a40', 'learn', 3, 'definition', '{"term":"Angular momentum","body":"$L = I\\omega$. With no external torque, $L$ is conserved: $I_1\\omega_1 = I_2\\omega_2$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c3decfee4ad65d', 'les_0625c4e2137a40', 'learn', 4, 'worked_example', '{"title":"A skater pulls in her arms, reducing I from 4 to 1.6 kg·m² while spinning at 2 rad/s","steps":[{"latex":"\\omega_2 = \\tfrac{I_1\\omega_1}{I_2} = \\tfrac{4(2)}{1.6} = 5\\ \\text{rad/s}","explanation":"She spins 2.5 times faster."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e95900312aed90', 'les_0625c4e2137a40', 'learn', 5, 'callout', '{"tone":"note","title":"Rolling races","body":"Rolling down a ramp, a solid sphere beats a solid disk, which beats a hoop. Shapes with less of their mass far out put less energy into spinning and more into moving forward, whatever their mass or radius."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_710d9f6cea11cf', 'les_0625c4e2137a40', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Divers tuck to spin faster, cats right themselves in midair, and a collapsing star''s spin speeds up enormously to form a pulsar."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e3d40f8c27d737', 'les_0625c4e2137a40', 1, 'practice', 'numeric', 2, 'Find the rotational inertia of a 3 kg hoop of radius 0.2 m.', '{"answer":0.12,"tolerance":0.001,"unit":"kg·m²"}', '[]', '$MR^2 = 3(0.04)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_cd4c49722cb435', 'les_0625c4e2137a40', 2, 'practice', 'numeric', 2, 'A wheel with I = 0.5 kg·m² gets a 2 N·m net torque. Find α.', '{"answer":4,"unit":"rad/s²"}', '[]', '$\frac{2}{0.5}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1516252e6a1d34', 'les_0625c4e2137a40', 3, 'practice', 'numeric', 3, 'A spinning stool (I = 3 kg·m²) turns at 2 rad/s. The rider extends weights so I = 6 kg·m². Find the new ω.', '{"answer":1,"unit":"rad/s"}', '[]', '$\frac{3(2)}{6}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c3decfee4ad65d', 'les_0625c4e2137a40', 4, 'review', 'multiple_choice', 3, 'When the skater pulls her arms in, her rotational kinetic energy…', '{"choices":["stays the same","increases","decreases","becomes zero"],"answer":1}', '[]', '$K = \frac{L^2}{2I}$: same $L$, smaller $I$. The extra energy comes from the work her muscles do.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_acaf3225435500', 'subj_phys', 'rotation', 'Rotational motion', 'Angular kinematics, torque, rotational inertia and angular momentum.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_0625c4e2137a40', (SELECT id FROM concepts WHERE slug = 'rotation'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_0625c4e2137a40', (SELECT id FROM formulas WHERE slug = 'rotational-dynamics'), 1);

-- Lesson: rotational-kinematics
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_de26000334e3a2', 'rotational-kinematics', 'Rotational kinematics', 'Describe spinning objects with angular position, velocity and acceleration, use the rotational kinematic equations, and connect them to linear motion.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0ea3e781714700', 'les_de26000334e3a2', 1, 'Measure angles in radians, and convert rpm to rad/s.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f7d70cc0d637dd', 'les_de26000334e3a2', 2, 'Use ω = ω₀ + αt and θ = ω₀t + ½αt².');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_beb9870c198d1d', 'les_de26000334e3a2', 3, 'Relate linear and angular quantities: s = rθ, v = rω, a_t = rα, a_c = rω².');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0ea3e781714700', 'les_de26000334e3a2', 'learn', 1, 'definition', '{"term":"Angular quantities","body":"Angular position $\\theta$ is in radians (one turn = $2\\pi$ rad). Angular velocity is $\\omega = \\frac{\\Delta\\theta}{\\Delta t}$ (rad/s), and angular acceleration is $\\alpha = \\frac{\\Delta\\omega}{\\Delta t}$ (rad/s²). The constant-$\\alpha$ equations mirror linear ones: $\\omega = \\omega_0 + \\alpha t$, $\\theta = \\omega_0 t + \\frac12\\alpha t^2$, $\\omega^2 = \\omega_0^2 + 2\\alpha\\theta$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f7d70cc0d637dd', 'les_de26000334e3a2', 'learn', 2, 'definition', '{"term":"Linking to linear motion","body":"A point at radius $r$ moves $s = r\\theta$ with speed $v = r\\omega$. Every point on a rigid wheel shares the same $\\omega$, but points farther out move faster."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_beb9870c198d1d', 'les_de26000334e3a2', 'learn', 3, 'worked_example', '{"title":"A wheel spins at 120 rpm","steps":[{"latex":"\\omega = 120 \\cdot \\tfrac{2\\pi}{60} = 4\\pi \\approx 12.6\\ \\text{rad/s}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bf404a13f8030e', 'les_de26000334e3a2', 'learn', 4, 'worked_example', '{"title":"A disk starts from rest with α = 2 rad/s² for 5 s","steps":[{"latex":"\\omega = 0 + 2(5) = 10\\ \\text{rad/s}","explanation":""},{"latex":"\\theta = \\tfrac12(2)(5^2) = 25\\ \\text{rad} \\approx 4\\ \\text{turns}","explanation":""},{"latex":"v = r\\omega = 0.3(10) = 3\\ \\text{m/s at}\\ r = 0.3\\ \\text{m}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2e8d010caddb54', 'les_de26000334e3a2', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"A car''s speedometer counts wheel rotations and multiplies by the wheel radius; oversized tires make it read too low."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0ea3e781714700', 'les_de26000334e3a2', 1, 'practice', 'numeric', 1, 'Convert 33.3 rpm (a vinyl record) to rad/s.', '{"answer":3.49,"tolerance":0.01,"unit":"rad/s"}', '[]', '$33.3 \cdot \frac{2\pi}{60}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f7d70cc0d637dd', 'les_de26000334e3a2', 2, 'practice', 'numeric', 2, 'Find the centripetal acceleration at r = 0.3 m when ω = 10 rad/s.', '{"answer":30,"unit":"m/s²"}', '[]', '$r\omega^2 = 0.3(100)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_beb9870c198d1d', 'les_de26000334e3a2', 3, 'practice', 'numeric', 2, 'A fan at 20 rad/s slows uniformly to rest in 4 s. Find α.', '{"answer":-5,"unit":"rad/s²"}', '[]', '$\frac{0 - 20}{4}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bf404a13f8030e', 'les_de26000334e3a2', 4, 'review', 'multiple_choice', 3, 'On a spinning merry-go-round, a child at the rim compared with one halfway out has…', '{"choices":["the same ω and twice the speed","twice ω and the same speed","the same ω and speed","half the speed"],"answer":0}', '[]', '$v = r\omega$ with $\omega$ shared.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_acaf3225435500', 'subj_phys', 'rotation', 'Rotational motion', 'Angular kinematics, torque, rotational inertia and angular momentum.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_de26000334e3a2', (SELECT id FROM concepts WHERE slug = 'rotation'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_de26000334e3a2', (SELECT id FROM formulas WHERE slug = 'rotational-dynamics'), 1);

-- Lesson: rotational-kinetic-energy-work
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_f25c64c5d277a2', 'rotational-kinetic-energy-work', 'Rotational kinetic energy and work', 'Compute rotational kinetic energy, the work done by a torque, and apply the work–energy theorem to spinning objects.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e27df152080050', 'les_f25c64c5d277a2', 1, 'Compute K_rot = ½Iω².');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_baaa6a889496df', 'les_f25c64c5d277a2', 2, 'Compute the work done by a constant torque, W = τΔθ.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1dbf26cb43c660', 'les_f25c64c5d277a2', 3, 'Apply the rotational work–energy theorem, W_net = ΔK_rot.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e27df152080050', 'les_f25c64c5d277a2', 'learn', 1, 'definition', '{"term":"Rotational kinetic energy","body":"A spinning object stores $K_{rot} = \\frac12 I\\omega^2$, the sum of $\\frac12 mv^2$ over all its parts. An object that both moves and spins has $K = \\frac12 Mv_{cm}^2 + \\frac12 I_{cm}\\omega^2$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_baaa6a889496df', 'les_f25c64c5d277a2', 'learn', 2, 'definition', '{"term":"Work by a torque","body":"A constant torque turning an object through $\\Delta\\theta$ (radians) does work $W = \\tau\\Delta\\theta$, and power $P = \\tau\\omega$. The work–energy theorem becomes $W_{net} = \\Delta K_{rot}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1dbf26cb43c660', 'les_f25c64c5d277a2', 'learn', 3, 'worked_example', '{"title":"A flywheel (I = 10 kg·m²) spins at 100 rad/s","steps":[{"latex":"K = \\tfrac12(10)(100^2) = 50{,}000\\ \\text{J}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_aac34f46c5bf8f', 'les_f25c64c5d277a2', 'learn', 4, 'worked_example', '{"title":"A 20 N·m torque turns a wheel through 5 revolutions","steps":[{"latex":"\\Delta\\theta = 5(2\\pi) = 10\\pi\\ \\text{rad}","explanation":""},{"latex":"W = 20(10\\pi) \\approx 628\\ \\text{J}","explanation":"If the wheel started at rest with no friction, that''s its final kinetic energy."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7367b81281e5df', 'les_f25c64c5d277a2', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Flywheel energy storage smooths power grids, and regenerative braking turns a vehicle''s kinetic energy into stored energy instead of heat."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e27df152080050', 'les_f25c64c5d277a2', 1, 'practice', 'numeric', 2, 'A 0.5 kg·m² wheel starts at rest; a 4 N·m torque acts for 2π rad. Find its final ω, to two decimal places.', '{"answer":10.03,"tolerance":0.02,"unit":"rad/s"}', '[]', '$W = 8\pi \approx 25.1$ J $= \frac12(0.5)\omega^2$, so $\omega = \sqrt{32\pi} \approx 10.03$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_baaa6a889496df', 'les_f25c64c5d277a2', 2, 'practice', 'numeric', 2, 'A motor delivers 50 N·m at 120 rad/s. Find its power.', '{"answer":6000,"unit":"W"}', '[]', '$\tau\omega$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1dbf26cb43c660', 'les_f25c64c5d277a2', 3, 'practice', 'multiple_choice', 2, 'Doubling a flywheel''s angular speed multiplies its stored energy by…', '{"choices":["2","4","8","½"],"answer":1}', '[]', '$K \propto \omega^2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_aac34f46c5bf8f', 'les_f25c64c5d277a2', 4, 'review', 'multiple_choice', 3, 'A hoop and a disk of equal mass and radius spin at the same ω. Which has more kinetic energy?', '{"choices":["the disk","the hoop","equal","neither has any"],"answer":1}', '[]', 'The hoop''s I is twice the disk''s.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_acaf3225435500', 'subj_phys', 'rotation', 'Rotational motion', 'Angular kinematics, torque, rotational inertia and angular momentum.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_f25c64c5d277a2', (SELECT id FROM concepts WHERE slug = 'rotation'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_f25c64c5d277a2', (SELECT id FROM formulas WHERE slug = 'rotational-dynamics'), 1);

-- Lesson: rotational-second-law
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_40a5f1f87281dc', 'rotational-second-law', 'Newton''s second law in rotational form', 'Apply τ = Iα to rigid bodies, combine it with F = ma for systems with massive pulleys, and use the parallel-axis theorem.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_335e4afa1675e5', 'les_40a5f1f87281dc', 1, 'Apply τ_net = Iα to rotating objects.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_00cfa4b5e9fbc5', 'les_40a5f1f87281dc', 2, 'Solve systems combining linear and rotational motion (massive pulleys).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1474a7b77d5141', 'les_40a5f1f87281dc', 3, 'Use the parallel-axis theorem, I = I_cm + Md².');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_335e4afa1675e5', 'les_40a5f1f87281dc', 'learn', 1, 'definition', '{"term":"Rotational second law","body":"$\\alpha = \\frac{\\tau_{net}}{I}$: a net torque produces angular acceleration, resisted by rotational inertia, just as $a = \\frac{F_{net}}{m}$. A massive pulley has different tensions on its two sides; their difference times $R$ is its net torque."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_00cfa4b5e9fbc5', 'les_40a5f1f87281dc', 'learn', 2, 'worked_example', '{"title":"A 2 kg mass hangs from a rope wrapped around a 4 kg solid-disk pulley (R = 0.1 m)","steps":[{"latex":"mg - T = ma \\quad\\text{and}\\quad TR = \\tfrac12 MR^2\\cdot\\tfrac{a}{R}","explanation":"Rope doesn''t slip, so α = a/R."},{"latex":"T = \\tfrac12 Ma","explanation":"From the torque equation."},{"latex":"a = \\tfrac{mg}{m + M/2} = \\tfrac{19.6}{4} = 4.9\\ \\text{m/s}^2","explanation":"Substituting into the hanging mass''s equation."},{"latex":"T = \\tfrac12(4)(4.9) = 9.8\\ \\text{N}","explanation":""},{"latex":"\\alpha = \\tfrac{4.9}{0.1} = 49\\ \\text{rad/s}^2","explanation":"Half of free fall: the disk''s inertia acts like an extra 2 kg."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1474a7b77d5141', 'les_40a5f1f87281dc', 'learn', 3, 'definition', '{"term":"Parallel-axis theorem","body":"For an axis parallel to one through the center of mass, a distance $d$ away: $I = I_{cm} + Md^2$. A uniform rod: $I_{cm} = \\frac{1}{12}ML^2$, so about one end $I = \\frac{1}{12}ML^2 + M\\left(\\frac L2\\right)^2 = \\frac13ML^2$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_19afbaaf126ec3', 'les_40a5f1f87281dc', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Flywheels resist speed changes, and a tightrope walker''s long pole has a large I, so a small torque gives a small, correctable wobble."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_335e4afa1675e5', 'les_40a5f1f87281dc', 1, 'practice', 'numeric', 2, 'Find the rotational inertia of a 3 kg, 1 m rod about one end.', '{"answer":1,"unit":"kg·m²"}', '[]', '$\frac13(3)(1)^2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_00cfa4b5e9fbc5', 'les_40a5f1f87281dc', 2, 'practice', 'numeric', 2, 'A grinding wheel (I = 0.2 kg·m²) is slowed by a 0.8 N·m friction torque. Find α.', '{"answer":-4,"unit":"rad/s²"}', '[]', '$\frac{-0.8}{0.2}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1474a7b77d5141', 'les_40a5f1f87281dc', 3, 'practice', 'numeric', 3, 'Repeat the pulley example with a massless pulley. Find a.', '{"answer":9.8,"unit":"m/s²"}', '[]', 'With $M = 0$, $a = g$: nothing else holds the mass back.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_19afbaaf126ec3', 'les_40a5f1f87281dc', 4, 'review', 'multiple_choice', 3, 'On a massive pulley with an accelerating rope, the tensions on the two sides are…', '{"choices":["always equal","different, and their difference produces the angular acceleration","zero","equal to the weights"],"answer":1}', '[]', '$(T_1 - T_2)R = I\alpha$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_acaf3225435500', 'subj_phys', 'rotation', 'Rotational motion', 'Angular kinematics, torque, rotational inertia and angular momentum.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_40a5f1f87281dc', (SELECT id FROM concepts WHERE slug = 'rotation'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_40a5f1f87281dc', (SELECT id FROM formulas WHERE slug = 'rotational-dynamics'), 1);

-- Lesson: shm-energy
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_252d4143cf51f0', 'shm-energy', 'Energy of simple harmonic oscillators', 'Track kinetic and potential energy through an oscillation, use E = ½kA², and find the speed at any position.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_20ef94d85928ce', 'les_252d4143cf51f0', 1, 'Show that total mechanical energy of an ideal oscillator is E = ½kA².');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1fafd3d3f86ef2', 'les_252d4143cf51f0', 2, 'Find the speed at any position using v = ω√(A² − x²).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_15e12d827348c2', 'les_252d4143cf51f0', 3, 'Interpret energy bar charts and energy–position graphs for SHM.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_20ef94d85928ce', 'les_252d4143cf51f0', 'learn', 1, 'definition', '{"term":"Energy in SHM","body":"Without friction, $E = \\frac12mv^2 + \\frac12kx^2$ is constant. At the turning points it''s all potential, $E = \\frac12kA^2$; at equilibrium it''s all kinetic, $E = \\frac12mv_{max}^2$. Solving for speed gives $v = \\omega\\sqrt{A^2 - x^2}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1fafd3d3f86ef2', 'les_252d4143cf51f0', 'learn', 2, 'worked_example', '{"title":"1 kg on a 100 N/m spring with A = 0.2 m","steps":[{"latex":"E = \\tfrac12(100)(0.2^2) = 2\\ \\text{J}","explanation":""},{"latex":"U(0.1) = \\tfrac12(100)(0.01) = 0.5\\ \\text{J}","explanation":"At x = 0.1 m."},{"latex":"K = 2 - 0.5 = 1.5\\ \\text{J}","explanation":""},{"latex":"v = 10\\sqrt{0.04 - 0.01} \\approx 1.73\\ \\text{m/s}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_15e12d827348c2', 'les_252d4143cf51f0', 'learn', 3, 'definition', '{"term":"On a graph","body":"On an energy–position graph, $U = \\frac12kx^2$ is a parabola, $E$ is a horizontal line, and the gap between them is $K$. The turning points are where the line meets the parabola."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_001253fafab172', 'les_252d4143cf51f0', 'experiment', 4, 'activity', '{"activity":"spring-oscillator","title":"Energy bars during an oscillation","params":{"mass":1,"k":100,"amplitude":0.2}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4592728a64c1ed', 'les_252d4143cf51f0', 'learn', 5, 'callout', '{"tone":"note","title":"Damping","body":"Real oscillators lose energy to friction, so the amplitude shrinks over time; the energy turns into heat. Car shock absorbers are designed to damp oscillations quickly."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_63efdca04eceaf', 'les_252d4143cf51f0', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Bungee jumps, guitar strings and atoms vibrating in a crystal all trade kinetic and potential energy back and forth."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_20ef94d85928ce', 'les_252d4143cf51f0', 1, 'practice', 'numeric', 2, 'A 200 N/m spring oscillates with amplitude 0.1 m. Find the total energy.', '{"answer":1,"unit":"J"}', '[]', '$\frac12(200)(0.01)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1fafd3d3f86ef2', 'les_252d4143cf51f0', 2, 'practice', 'numeric', 2, 'At what fraction of the amplitude is the energy half kinetic and half potential? Give a decimal to three places.', '{"answer":0.707,"tolerance":0.002}', '[]', '$\frac12kx^2 = \frac14kA^2$, so $x = \frac{A}{\sqrt2}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_15e12d827348c2', 'les_252d4143cf51f0', 3, 'practice', 'numeric', 3, 'A 0.5 kg mass on a spring has E = 4 J. Find v_max.', '{"answer":4,"unit":"m/s"}', '[]', '$\frac12(0.5)v^2 = 4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_001253fafab172', 'les_252d4143cf51f0', 4, 'review', 'multiple_choice', 3, 'Doubling the amplitude multiplies the total energy by…', '{"choices":["2","4","√2","1"],"answer":1}', '[]', '$E \propto A^2$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_252d4143cf51f0', (SELECT id FROM concepts WHERE slug = 'simple-harmonic-motion'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_252d4143cf51f0', (SELECT id FROM formulas WHERE slug = 'work-energy'), 1);

-- Lesson: shm-graphs-analysis
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_f3dc3204452d3d', 'shm-graphs-analysis', 'Representing and analyzing SHM', 'Write and interpret x(t) = A cos(ωt + φ), relate the position, velocity and acceleration graphs, and find maximum speed and acceleration.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a763cf0deb6e3b', 'les_f3dc3204452d3d', 1, 'Write the position of a simple harmonic oscillator as x(t) = A cos(ωt + φ).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0e72b4aff29b9d', 'les_f3dc3204452d3d', 2, 'Relate the graphs of x, v and a, including their phase differences.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_122cb5ccd83474', 'les_f3dc3204452d3d', 3, 'Compute v_max = Aω and a_max = Aω².');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a763cf0deb6e3b', 'les_f3dc3204452d3d', 'learn', 1, 'definition', '{"term":"Equations of motion","body":"Released from rest at $x = A$: $x(t) = A\\cos(\\omega t)$. Then $v(t) = -A\\omega\\sin(\\omega t)$ and $a(t) = -A\\omega^2\\cos(\\omega t) = -\\omega^2 x$. The defining feature of SHM is that acceleration is proportional to displacement and opposite to it."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0e72b4aff29b9d', 'les_f3dc3204452d3d', 'learn', 2, 'definition', '{"term":"Reading the graphs","body":"Speed is greatest at equilibrium ($x = 0$) and zero at the turning points. Acceleration is greatest in magnitude at the turning points and zero at equilibrium. The velocity graph is a quarter-cycle behind the position graph."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_122cb5ccd83474', 'les_f3dc3204452d3d', 'learn', 3, 'worked_example', '{"title":"A 1 kg mass on a 100 N/m spring, pulled 0.2 m and released","steps":[{"latex":"\\omega = \\sqrt{\\tfrac{k}{m}} = 10\\ \\text{rad/s}","explanation":""},{"latex":"v_{max} = A\\omega = 2\\ \\text{m/s},\\ a_{max} = A\\omega^2 = 20\\ \\text{m/s}^2","explanation":""},{"latex":"x(t) = 0.2\\cos(10t)","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_86d03bf7538f58', 'les_f3dc3204452d3d', 'experiment', 4, 'activity', '{"activity":"spring-oscillator","title":"Watch position and speed through a cycle","params":{"mass":1,"k":100,"amplitude":0.2}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_78f989bc5b4b08', 'les_f3dc3204452d3d', 'experiment', 5, 'activity', '{"activity":"sinusoid","title":"Amplitude, period and phase of a cosine","params":{}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_675b88a4b6c7e8', 'les_f3dc3204452d3d', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Seismographs, AC voltage and audio signals are all described by sinusoids, and engineers read their phase lags from graphs like these."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a763cf0deb6e3b', 'les_f3dc3204452d3d', 1, 'practice', 'numeric', 2, 'An oscillator has x(t) = 0.05 cos(4πt). Find its period.', '{"answer":0.5,"unit":"s"}', '[]', '$\omega = 4\pi = \frac{2\pi}{T}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0e72b4aff29b9d', 'les_f3dc3204452d3d', 2, 'practice', 'numeric', 2, 'Find v_max for that oscillator, to three decimal places.', '{"answer":0.628,"tolerance":0.002,"unit":"m/s"}', '[]', '$0.05(4\pi)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_122cb5ccd83474', 'les_f3dc3204452d3d', 3, 'practice', 'multiple_choice', 2, 'At the moment x = +A, the acceleration is…', '{"choices":["zero","maximum and negative","maximum and positive","equal to the velocity"],"answer":1}', '[]', '$a = -\omega^2 x$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_86d03bf7538f58', 'les_f3dc3204452d3d', 4, 'review', 'multiple_choice', 3, 'Doubling the amplitude of a spring oscillator multiplies v_max by…', '{"choices":["1","√2","2","4"],"answer":2}', '[]', '$v_{max} = A\omega$; ω is unchanged.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_f3dc3204452d3d', (SELECT id FROM concepts WHERE slug = 'simple-harmonic-motion'));

-- Lesson: specific-heat-phase-changes
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_53b1cf6481bf15', 'specific-heat-phase-changes', 'Specific heat and phase changes', 'Compute heat with Q = mcΔT and Q = mL, read heating curves, and solve calorimetry problems with conservation of energy.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_4544ef7a3c82fd', 'les_53b1cf6481bf15', 1, 'Use Q = mcΔT for temperature changes.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_81bd85f6698d2d', 'les_53b1cf6481bf15', 2, 'Use Q = mL for melting and boiling, at constant temperature.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c47bc1385a5471', 'les_53b1cf6481bf15', 3, 'Solve mixing problems: heat lost = heat gained.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4544ef7a3c82fd', 'les_53b1cf6481bf15', 'learn', 1, 'definition', '{"term":"Specific heat","body":"The heat needed to change a mass''s temperature is $Q = mc\\Delta T$, where $c$ is the specific heat. Water has an unusually large $c = 4186$ J/(kg·°C); aluminum''s is about 900 and copper''s 385."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_81bd85f6698d2d', 'les_53b1cf6481bf15', 'learn', 2, 'worked_example', '{"title":"Heat 2 kg of water from 20 °C to 100 °C","steps":[{"latex":"Q = 2(4186)(80) = 669{,}760\\ \\text{J} \\approx 670\\ \\text{kJ}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c47bc1385a5471', 'les_53b1cf6481bf15', 'learn', 3, 'definition', '{"term":"Phase changes","body":"During melting or boiling, added heat breaks bonds instead of raising the temperature: $Q = mL$. For water, $L_f = 3.34\\times10^5$ J/kg and $L_v = 2.26\\times10^6$ J/kg. A heating curve shows rising slopes (one phase warming) separated by flat plateaus (phase changes)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a53f6fb821385c', 'les_53b1cf6481bf15', 'learn', 4, 'worked_example', '{"title":"Melt 0.5 kg of ice at 0 °C, then boil 0.1 kg of water at 100 °C","steps":[{"latex":"Q_{melt} = 0.5(3.34\\times10^5) = 167{,}000\\ \\text{J}","explanation":""},{"latex":"Q_{boil} = 0.1(2.26\\times10^6) = 226{,}000\\ \\text{J}","explanation":"Boiling takes far more energy per kilogram."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_128cd00b31e73e', 'les_53b1cf6481bf15', 'learn', 5, 'worked_example', '{"title":"Mix 0.2 kg of water at 80 °C with 0.3 kg at 20 °C","steps":[{"latex":"0.2c(80 - T) = 0.3c(T - 20)","explanation":"Heat lost by the hot water equals heat gained by the cool water."},{"latex":"16 - 0.2T = 0.3T - 6 \\Rightarrow T = 44\\ °\\text{C}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0e29861501f136', 'les_53b1cf6481bf15', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Water''s high specific heat keeps coastal climates mild and makes it a good coolant; steam burns are worse than boiling-water burns because condensing steam releases its latent heat."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4544ef7a3c82fd', 'les_53b1cf6481bf15', 1, 'practice', 'numeric', 2, 'How much heat warms 0.5 kg of aluminum (c = 900) by 30 °C?', '{"answer":13500,"unit":"J"}', '[]', '$0.5(900)(30)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_81bd85f6698d2d', 'les_53b1cf6481bf15', 2, 'practice', 'numeric', 2, 'How much heat melts 2 kg of ice at 0 °C?', '{"answer":668000,"unit":"J"}', '[]', '$2(3.34\times10^5)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c47bc1385a5471', 'les_53b1cf6481bf15', 3, 'practice', 'numeric', 3, 'Mix 1 kg of water at 90 °C with 2 kg at 30 °C. Find the final temperature.', '{"answer":50,"unit":"°C"}', '[]', '$\frac{1(90) + 2(30)}{3}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a53f6fb821385c', 'les_53b1cf6481bf15', 4, 'review', 'multiple_choice', 3, 'On a heating curve, the temperature stays constant during boiling because…', '{"choices":["no heat is added","the energy goes into breaking bonds between molecules","the thermometer breaks","heat flows out as fast as it enters"],"answer":1}', '[]', 'Energy changes the potential energy of the molecules, not their kinetic energy.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_6cf11d103edcfe', 'subj_phys', 'thermal-physics', 'Thermal physics', 'Temperature, heat, phase changes and the laws of thermodynamics.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_53b1cf6481bf15', (SELECT id FROM concepts WHERE slug = 'thermal-physics'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_53b1cf6481bf15', (SELECT id FROM formulas WHERE slug = 'heat-thermodynamics'), 1);

-- Lesson: spring-forces
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_6b4011c49d0153', 'spring-forces', 'Spring forces and Hooke''s law', 'Use Hooke''s law F = −kx, find spring constants from data, analyze hanging masses, and combine springs.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b1b90003f2266e', 'les_6b4011c49d0153', 1, 'Apply Hooke''s law, F = −kx, and interpret its sign.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9c82766ffe7af8', 'les_6b4011c49d0153', 2, 'Find a spring constant from a force–stretch graph.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0d0be2a8e80330', 'les_6b4011c49d0153', 3, 'Find equilibrium stretch and effective spring constants of springs in series and parallel.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b1b90003f2266e', 'les_6b4011c49d0153', 'learn', 1, 'definition', '{"term":"Hooke''s law","body":"An ideal spring stretched or compressed by $x$ from its natural length pushes back with $F_s = -kx$. The minus sign means the force points toward equilibrium. The spring constant $k$ (N/m) measures stiffness and is the slope of a force-versus-stretch graph."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9c82766ffe7af8', 'les_6b4011c49d0153', 'learn', 2, 'worked_example', '{"title":"A 2 N force stretches a spring 4 cm","steps":[{"latex":"k = \\tfrac{F}{x} = \\tfrac{2}{0.04} = 50\\ \\text{N/m}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0d0be2a8e80330', 'les_6b4011c49d0153', 'learn', 3, 'worked_example', '{"title":"A 0.5 kg mass hangs at rest from a 200 N/m spring","steps":[{"latex":"kx = mg \\Rightarrow x = \\tfrac{0.5(9.8)}{200} = 0.0245\\ \\text{m}","explanation":"About 2.5 cm."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d6b24d06b436b5', 'les_6b4011c49d0153', 'learn', 4, 'definition', '{"term":"Combining springs","body":"Side by side (parallel): $k_{eff} = k_1 + k_2$, stiffer. End to end (series): $\\frac{1}{k_{eff}} = \\frac{1}{k_1} + \\frac{1}{k_2}$, softer. That''s the opposite of the rule for resistors."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5b257adb997843', 'les_6b4011c49d0153', 'experiment', 5, 'activity', '{"activity":"spring-oscillator","title":"Feel the spring constant","params":{"mass":0.5,"k":50,"amplitude":0.2}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e9b38967b20360', 'les_6b4011c49d0153', 'learn', 6, 'callout', '{"tone":"warning","title":"Limits","body":"Hooke''s law holds only up to the elastic limit; stretch a spring too far and it deforms permanently."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6ed366a25209ae', 'les_6b4011c49d0153', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Spring scales, car suspensions, mattresses and atomic bonds (modelled as tiny springs) all follow Hooke''s law for small stretches."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b1b90003f2266e', 'les_6b4011c49d0153', 1, 'practice', 'numeric', 2, 'A 300 N/m spring is compressed 0.1 m. Find the size of its force.', '{"answer":30,"unit":"N"}', '[]', '$kx$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9c82766ffe7af8', 'les_6b4011c49d0153', 2, 'practice', 'numeric', 2, 'Two 100 N/m springs are connected end to end. Find the effective spring constant.', '{"answer":50,"unit":"N/m"}', '[]', '$\frac{1}{k} = \frac{1}{100} + \frac{1}{100}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0d0be2a8e80330', 'les_6b4011c49d0153', 3, 'practice', 'numeric', 3, 'A 2 kg mass hangs from two identical parallel springs and stretches them 0.049 m. Find each spring''s constant.', '{"answer":200,"unit":"N/m"}', '[]', '$k_{eff} = \frac{19.6}{0.049} = 400$, split between two springs.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d6b24d06b436b5', 'les_6b4011c49d0153', 4, 'review', 'multiple_choice', 3, 'A spring is cut in half. Each half''s spring constant is…', '{"choices":["half the original","the same","twice the original","four times the original"],"answer":2}', '[]', 'The original is two halves in series: $\frac1k = \frac{2}{k_{half}}$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_6b4011c49d0153', (SELECT id FROM concepts WHERE slug = 'newtons-laws'));

-- Lesson: systems-center-of-mass
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_d0c4528fa98059', 'systems-center-of-mass', 'Systems and center of mass', 'Choose systems, locate the center of mass of several objects, and use the fact that only external forces change the motion of the center of mass.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5bb6d3234cf403', 'les_d0c4528fa98059', 1, 'Define a system and tell internal forces from external ones.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_dc0a0d1d805b3f', 'les_d0c4528fa98059', 2, 'Compute the center of mass of point masses: x_cm = Σmx/Σm.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5d9002943ca8d3', 'les_d0c4528fa98059', 3, 'Explain why the center of mass moves as if all external forces acted on a single particle.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5bb6d3234cf403', 'les_d0c4528fa98059', 'learn', 1, 'definition', '{"term":"Systems","body":"A system is whatever collection of objects you choose to analyze. Forces between objects inside the system are internal and cancel in pairs (Newton''s third law). Only external forces change the motion of the system as a whole: $\\sum \\vec F_{ext} = M\\vec a_{cm}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_dc0a0d1d805b3f', 'les_d0c4528fa98059', 'learn', 2, 'definition', '{"term":"Center of mass","body":"For point masses along a line, $x_{cm} = \\frac{m_1x_1 + m_2x_2 + \\cdots}{m_1 + m_2 + \\cdots}$, and likewise for $y$. For a uniform symmetric object, the center of mass is at its geometric center. It lies closer to the heavier mass."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5d9002943ca8d3', 'les_d0c4528fa98059', 'learn', 3, 'worked_example', '{"title":"2 kg at x = 0 and 3 kg at x = 5 m","steps":[{"latex":"x_{cm} = \\tfrac{2(0) + 3(5)}{5} = 3\\ \\text{m}","explanation":"Closer to the 3 kg mass."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d51935ade7b051', 'les_d0c4528fa98059', 'learn', 4, 'worked_example', '{"title":"The Earth–Moon system (Earth 5.97 × 10²⁴ kg, Moon 7.35 × 10²² kg, 3.84 × 10⁸ m apart)","steps":[{"latex":"x_{cm} = \\tfrac{m_M d}{M_E + m_M}","explanation":"Measured from Earth''s center, where Earth''s own term is zero."},{"latex":"x_{cm} = \\tfrac{(7.35\\times10^{22})(3.84\\times10^8)}{6.04\\times10^{24}}","explanation":""},{"latex":"x_{cm} \\approx 4.67\\times10^6\\ \\text{m}","explanation":"Inside Earth (radius 6.37 × 10⁶ m); both bodies orbit this point."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f9a5019783bceb', 'les_d0c4528fa98059', 'learn', 5, 'callout', '{"tone":"note","title":"Explosions","body":"If a firework shell bursts in midair, the internal forces can''t change the center of mass''s motion: it keeps following the original parabola until fragments hit the ground."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_19abf35b4dc42e', 'les_d0c4528fa98059', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"High jumpers arch over the bar so their center of mass can pass below it; trucks tip when their center of mass moves outside the wheelbase."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5bb6d3234cf403', 'les_d0c4528fa98059', 1, 'practice', 'numeric', 1, '1 kg sits at x = 0 and 4 kg at x = 10 m. Find the center of mass.', '{"answer":8,"unit":"m"}', '[]', '$\frac{4(10)}{5}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_dc0a0d1d805b3f', 'les_d0c4528fa98059', 2, 'practice', 'numeric', 2, 'Masses of 2 kg at (0, 0), 2 kg at (4, 0) and 4 kg at (2, 3). Find $y_{cm}$.', '{"answer":1.5,"unit":"m"}', '[]', '$\frac{4(3)}{8}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5d9002943ca8d3', 'les_d0c4528fa98059', 3, 'practice', 'multiple_choice', 2, 'Two skaters push off each other on frictionless ice. Their center of mass…', '{"choices":["moves toward the heavier skater","stays at rest","moves toward the lighter skater","accelerates"],"answer":1}', '[]', 'Only internal forces act horizontally.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d51935ade7b051', 'les_d0c4528fa98059', 4, 'review', 'multiple_choice', 3, 'Choosing "both carts" as the system in a collision means the collision forces are…', '{"choices":["external","internal, so they don''t change the total momentum","zero","unbalanced"],"answer":1}', '[]', 'Internal forces cancel in pairs.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_d0c4528fa98059', (SELECT id FROM concepts WHERE slug = 'newtons-laws'));

-- Lesson: temperature-thermal-energy
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_f02d0a4d8e965f', 'temperature-thermal-energy', 'Temperature and thermal energy', 'Connect temperature to molecular motion, convert between temperature scales, distinguish heat from temperature, and compute thermal expansion.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_442cf53f24ca61', 'les_f02d0a4d8e965f', 1, 'Relate temperature to the average kinetic energy of particles.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3e0009722e773f', 'les_f02d0a4d8e965f', 2, 'Convert among Celsius, Fahrenheit and kelvin.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8fd1011ff72428', 'les_f02d0a4d8e965f', 3, 'Describe conduction, convection and radiation, and compute ΔL = αLΔT.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_442cf53f24ca61', 'les_f02d0a4d8e965f', 'learn', 1, 'definition', '{"term":"Temperature and heat","body":"Temperature measures the average kinetic energy of a substance''s particles. Thermal energy is the total kinetic and potential energy of all of them. Heat is energy transferred because of a temperature difference, always from hot to cold, until thermal equilibrium."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3e0009722e773f', 'les_f02d0a4d8e965f', 'learn', 2, 'definition', '{"term":"Scales","body":"$T_K = T_C + 273.15$ and $T_F = \\frac95 T_C + 32$. Absolute zero (0 K, −273.15 °C) is where particle motion is at its minimum. Gas laws need kelvin."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8fd1011ff72428', 'les_f02d0a4d8e965f', 'learn', 3, 'worked_example', '{"title":"Convert 25 °C","steps":[{"latex":"T_K = 25 + 273.15 = 298.15\\ \\text{K}","explanation":""},{"latex":"T_F = \\tfrac95(25) + 32 = 77\\ °\\text{F}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4fb94ab8778755', 'les_f02d0a4d8e965f', 'learn', 4, 'definition', '{"term":"Heat transfer and expansion","body":"Heat moves by conduction (contact), convection (moving fluid) and radiation (electromagnetic waves, even through vacuum). Most materials expand when heated: $\\Delta L = \\alpha L \\Delta T$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b968f1f7d1ef16', 'les_f02d0a4d8e965f', 'learn', 5, 'worked_example', '{"title":"A 100 m steel bridge (α = 12 × 10⁻⁶ /°C) warms by 40 °C","steps":[{"latex":"\\Delta L = (12\\times10^{-6})(100)(40) = 0.048\\ \\text{m}","explanation":"Nearly 5 cm, so bridges need expansion joints."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a406f009f9b5a8', 'les_f02d0a4d8e965f', 'experiment', 6, 'activity', '{"activity":"ideal-gas","title":"Temperature as molecular motion"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a42024d0e5e6a8', 'les_f02d0a4d8e965f', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Thermostats use bimetallic strips that bend as two metals expand differently; double-pane windows slow conduction; the Sun warms Earth by radiation."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_442cf53f24ca61', 'les_f02d0a4d8e965f', 1, 'practice', 'numeric', 1, 'Convert 100 °F to Celsius, to one decimal place.', '{"answer":37.8,"tolerance":0.1,"unit":"°C"}', '[]', '$\frac59(100 - 32)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3e0009722e773f', 'les_f02d0a4d8e965f', 2, 'practice', 'numeric', 1, 'Convert 300 K to Celsius, to two decimal places.', '{"answer":26.85,"tolerance":0.01,"unit":"°C"}', '[]', '$300 - 273.15$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8fd1011ff72428', 'les_f02d0a4d8e965f', 3, 'practice', 'numeric', 2, 'A 2 m aluminum rod (α = 23 × 10⁻⁶ /°C) heats by 50 °C. Find its expansion in mm.', '{"answer":2.3,"tolerance":0.01,"unit":"mm"}', '[]', '$23\times10^{-6}(2)(50) = 0.0023$ m.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4fb94ab8778755', 'les_f02d0a4d8e965f', 4, 'review', 'multiple_choice', 3, 'A metal spoon feels colder than a wooden one at the same temperature because…', '{"choices":["metal is colder","metal conducts heat away from your hand faster","wood is warmer","metal radiates more"],"answer":1}', '[]', 'Same temperature; different conductivity.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_6cf11d103edcfe', 'subj_phys', 'thermal-physics', 'Thermal physics', 'Temperature, heat, phase changes and the laws of thermodynamics.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_f02d0a4d8e965f', (SELECT id FROM concepts WHERE slug = 'thermal-physics'));

-- Lesson: torque-equilibrium
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_15eedc552295fd', 'torque-equilibrium', 'Torque and static equilibrium', 'Compute torque from force, lever arm and angle, and use the two conditions for static equilibrium to balance seesaws and beams.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_954bd8b427aab6', 'les_15eedc552295fd', 1, 'Compute torque τ = rF sin θ and identify its direction.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_eba76727ddebeb', 'les_15eedc552295fd', 2, 'State the two conditions for static equilibrium: ΣF = 0 and Στ = 0.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_50b29348ff2125', 'les_15eedc552295fd', 3, 'Solve balance problems by choosing a convenient pivot.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_954bd8b427aab6', 'les_15eedc552295fd', 'learn', 1, 'definition', '{"term":"Torque","body":"Torque measures a force''s turning effect: $\\tau = rF\\sin\\theta$, where $r$ is the distance from the pivot and $\\theta$ the angle between $\\vec r$ and $\\vec F$. It''s largest when you push perpendicular to the lever, and zero when you push straight toward the pivot. Units: N·m."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_eba76727ddebeb', 'les_15eedc552295fd', 'learn', 2, 'worked_example', '{"title":"A 40 N force on a 0.25 m wrench","steps":[{"latex":"\\text{perpendicular: } \\tau = 0.25(40) = 10\\ \\text{N·m}","explanation":""},{"latex":"\\text{at 60°: } \\tau = 0.25(40)\\sin 60° \\approx 8.66\\ \\text{N·m}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_50b29348ff2125', 'les_15eedc552295fd', 'learn', 3, 'definition', '{"term":"Static equilibrium","body":"An object at rest stays at rest only if both the net force and the net torque about any point are zero: $\\sum F = 0$ and $\\sum\\tau = 0$. For a seesaw: $m_1 g d_1 = m_2 g d_2$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_47f7fd8ff45431', 'les_15eedc552295fd', 'experiment', 4, 'activity', '{"activity":"torque-balance","title":"Balance the seesaw","params":{"m1":4,"d1":1.5,"m2":6,"d2":1}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_675e7fed53084f', 'les_15eedc552295fd', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"The default setup balances: $4 \\times 1.5 = 6 \\times 1$. Move the 6 kg mass to 1.5 m and watch which way it tips, then find a new spot for the 4 kg mass that balances it."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3a9d70dfa783e7', 'les_15eedc552295fd', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Door handles sit far from the hinges, cranes carry counterweights, and engineers check $\\sum\\tau = 0$ for every bridge and balcony."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_954bd8b427aab6', 'les_15eedc552295fd', 1, 'practice', 'numeric', 2, 'A 30 kg child sits 2 m from a seesaw''s pivot. How far on the other side must a 40 kg child sit to balance?', '{"answer":1.5,"unit":"m"}', '[]', '$30(2) = 40d$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_eba76727ddebeb', 'les_15eedc552295fd', 2, 'practice', 'numeric', 2, 'A 50 N force pushes at 30° to a 0.4 m lever. Find the torque.', '{"answer":10,"unit":"N·m"}', '[]', '$0.4(50)\sin 30°$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_50b29348ff2125', 'les_15eedc552295fd', 3, 'practice', 'numeric', 3, 'A uniform 4 m, 10 kg plank rests on supports at its ends. A 20 kg box sits 1 m from the left end. Find the force from the right support (g = 9.8).', '{"answer":98,"tolerance":0.1,"unit":"N"}', '[]', 'Torques about the left end: $F_R(4) = 98(2) + 196(1)$, so $F_R = 98$ N.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_47f7fd8ff45431', 'les_15eedc552295fd', 4, 'review', 'multiple_choice', 3, 'Why is a door hard to open if you push near the hinges?', '{"choices":["The force is smaller","The lever arm is small, so the torque is small","Friction is greater there","The door is heavier there"],"answer":1}', '[]', '$\tau = rF$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_acaf3225435500', 'subj_phys', 'rotation', 'Rotational motion', 'Angular kinematics, torque, rotational inertia and angular momentum.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_15eedc552295fd', (SELECT id FROM concepts WHERE slug = 'rotation'));
